\label{def:constcont}
\begin{enumerate}
    \item Let $\Omega \subset \mathbb{R}^d$ be an open and bounded domain with ${d}\in\{2,3\}$.
    \item Define the bond stretch function $\mathcal{S}: \operatorname{Map}(\Omega, \mathbb{R}^d)\times \Omega\times\Omega \rightarrow \mathbb{R}$, defined by
    \begin{align*}
         \mathcal{S}({u}, x',x) = \frac{\|{u}(x')-{u}(x) + x'-x\|_2}{\|x'-x\|_2} -1.
    \end{align*}
    \item For a given displacement $u\in L^\infty(\Omega)^d$ at a time $t$ and a given $x\in\Omega$, we will call a bond $x'-x$ with $x'\in\Omega$ \textit{sub-critical} if $\mathcal{S}(u,x',x) < S^-_1$. Note that this includes the degenerate case $\|{u}(x')-{u}(x)+x'-x\|_2 = 0$, corresponding to the motion mapping the points $x',x\in \Omega$ onto the same image.
    \item Define the direction function for the motion $e: \operatorname{Map}(\Omega, \mathbb{R}^d)\times \Omega\times\Omega \rightarrow \mathbb{R}^d$, given by
    \begin{align*}
        e({u}, x',x) = \frac{{u}(x')-{u}(x)+x'-x}{\|{u}(x')-{u}(x)+x'-x\|_2}
    \end{align*}
    if the bond $x'-x$ at $x$ is not degenerate and $0$ otherwise.
    \item A horizon $\delta>0$ and a measurable weighting function $\omega_\delta: (0,\infty) \rightarrow \mathbb{R}_{\geq 0}$, fulfilling
    \begin{equation}
        \label{eqn:weightingfunctionintegcond}
        \text{ supp}(\omega_\delta(\|\cdot\|_2)) \subset B_\delta(0), \ \ \mathcal{L} :=\int_{\mathbb{R}^d} \frac{\omega_\delta(\|\zeta\|_2)}{\|\zeta\|_2}\ \mathbf{d} \zeta<\infty.
    \end{equation}
    \item A terminal time $0 <T <\infty$.
    \item Constants $-1<S^-_1<S^-_0<0<S^+_0<S^+_1<\infty$, and the relaxed force scalar and damage function,
    \begin{equation}
    \label{eqn:rfsbbfdef}
        g(s) = \begin{cases}
            0 & s < S^-_1 \\
            S^-_0\tfrac{s-S^-_1}{S^-_0 - S^-_1} & S^-_1 \leq s\leq S^-_0 \\
            s & S^-_0 \leq s \leq S^+_0\\
            S^+_0\tfrac{S^+_1-s}{S^+_1 - S^+_0} & S^+_0 < s < S^+_1\\
            0 & S^+_1 \leq s
        \end{cases},\hspace{0.5cm} \mu(s) = \begin{cases}
            1 & s \leq S^+_0 \\
            \tfrac{S^+_1-s}{S^+_1 - S^+_0} & S^+_0 < s < S^+_1\\
            0 & s \geq S^+_1.
        \end{cases}
    \end{equation}
    Note that both these functions are Lipschitz continuous with constant \\
    $\ell := \max\Big(1, \tfrac{\max(1, S^+_0)}{S^+_1-S^+_0}, \tfrac{|S^-_0|}{S^-_0-S^-_1}\Big)>0$. We further define $g^+:= \max_{s\in \mathbb{R}} |g(s)| = \max (|S^+_0|, |S^-_0|)$
    \item The force density $\mathbf{f}: \Omega \times \Omega \times C^0([-T,0], L^\infty(\Omega)^d) \rightarrow \mathbb{R}^d$ defined for almost all $x$ and almost all $x'$, by
    \begin{equation}\label{eqn:defcontfinteg}
        \mathbf{f}(x', x, \mathbf{u}) = \omega_\delta(\|x'-x\|_2)g(\mathcal{S}(\mathbf{u}(0), x', x))\mu\Big(\operatorname*{ess\,sup}_{-T\leq s\leq 0}\mathcal{S}([\Gamma\mathbf{u}](s), x', x) \Big)e(\mathbf{u}(0), x',x),
    \end{equation}
    where the essential supremum over $s\in [-T, 0]$ is evaluated over a jointly measurable representative $\Gamma\mathbf{u}\in L^\infty([-T,0]\times \Omega)^d$ of $\mathbf{u} \in C^0([-T,0], L^\infty(\Omega)^d)$ (see Remark \ref{rm:jointmesrepr}). 
    \item The above definitions then culminate in the non-local peridynamic operator\\ $F: C^0([-T, 0], L^\infty(\Omega)^d) \rightarrow L^\infty(\Omega)^d$ given by 
    \begin{equation}\label{eqn:defcontF}
        F(\mathbf{u})(x) = \int_{\Omega} \mathbf{f}(x',x, \mathbf{u}) \ \mathbf{d} x'.
    \end{equation}
    Note that by construction, $g(\mathcal{S}(u,x',x))=0$ for sub-critical bonds $x'-x$. Most specifically, $F(\mathbf{u})$ does not depend on the value of $e$ in degenerate bonds. We will make use of this degree of freedom in many proofs later on.
\end{enumerate}

\label{rm:jointmesrepr}

For every $\mathbf{u} \in C^0([-T,0], L^\infty(\Omega)^d)$ we construct a $\Gamma \mathbf{u}\in L^\infty([-T,0]\times\Omega)^d$ such that $[\Gamma \mathbf{u}](t, \cdot) = \mathbf{u}(t)$ a.e. $t\in [-T,0]$ in $L^\infty(\Omega)^d$. This is done such that the following diagram commutes, where unlabeled arrows represent canonical inclusions,
\begin{equation*}
    \xymatrix{
        C^0([-T,0], L^\infty(\Omega)^d) \ar@{_{(}->}[d]\ar@{_{(}->}[r]^{\Gamma} & L^\infty([-T,0] \times \Omega)^d  \ar@{_{(}->}[dd]\\
        C^0([-T,0], L^2(\Omega)^d) \ar@{_{(}->}[d] \\
        L^2([-T,0], L^2(\Omega)^d) \ar@{_{(}->>}[r]^{\Phi} & L^2([-T,0]\times \Omega)^d.
    }
\end{equation*}
The map $\Phi :L^2([-T,0], L^2(\Omega)^d) \simeq L^2([-T,0]\times \Omega)^d$ is constructed in \cite{anainbanachsp}, Proposition 1.2.24, and fulfills $[\Gamma \mathbf{u}](t,\cdot) = \mathbf{u}(t)$ for almost all $t\in [-T,0]$ in $L^2(\Omega)^d$ for any $\mathbf{u}\in L^2([-T,0], L^2(\Omega)^d)$.\par
This in particular implies for a given $\mathbf{u}\in C^0([-T,0], L^\infty(\Omega)^d)$, 
\begin{align*}
    \|\Gamma \mathbf{u}\|_{L^\infty([-T,0]\times \Omega)^d}& = \operatorname*{ess\,sup}_{t,x}  \|[\Gamma \mathbf{u}](t,x)\|_\infty\\
    &= \operatorname*{ess\,sup}_{x} \operatorname*{ess\,sup}_{t} \|[\Gamma \mathbf{u}](t,x)\|_\infty  \\
    &= \operatorname*{ess\,sup}_{t} \operatorname*{ess\,sup}_{x} \|[\Gamma \mathbf{u}](t,x)\|_\infty  \\
    &= \operatorname*{ess\,sup}_{t} \|[\Gamma \mathbf{u}](t,\cdot)\|_{L^\infty(\Omega)^d } \\
    &= \operatorname*{ess\,sup}_{t} \|\mathbf{u}(t)\|_{L^\infty(\Omega)^d} = \|\mathbf{u}\|_{C^0([-T,0], L^\infty(\Omega)^d)}.  
\end{align*}

\label{rm:relaxation} The functions $g$ and $\mu$ as defined in (\ref{eqn:rfsbbfdef}) are Lipschitz relaxations introduced in \cite{WP_FRAC} of the functions 
\begin{equation*}
    g(x) \equiv x \chi_{[-1, S^+_1]}(x), \ \ \mu(x) = \chi_{(-\infty, S^+_1)}(x)
\end{equation*}
as used in \cite{SillMeshFree}. The force scalar $g$ was introduced in \cite{WP_FRAC} to control the interaction of particles $x,x'$ with bond-stretch near $S_1^-$. More specifically, the cutoff of the force scalar $g$ at $S^-_1>-1$ is essential to the well-posedness proof given in \cite{WP_FRAC} as well as to the results stated in this paper. In total, the relaxation changes the original model in \cite{SillMeshFree} in two ways.
\begin{enumerate}
    \item The relaxation of $\mu$ and $g$ at $S_1^+$, $S_0^+$: This can also be interpreted mechanically as allowing the bond to weaken first before breaking, as noted in \cite{WP_FRAC, Emmrich2016}. \newline
    {The concept of allowing a continuous weakening before breaking is not new and has been noted in \cite{NIAZI2021102855} to be desirable for controlling the influence of the horizon on the strength and fracture energy of models without pre-cracks as given in this paper.}
    \item The relaxation of $g$ at $S_1^-$, $S_0^-$: This cutoff introduces physically undesirable behavior, weakening bond interactions if bonds are compressed beyond a stretch of $S^-_0$, making them reversibly fail below $S^-_1$. Note that by definition, $\mathcal{S}(u,x',x) \geq -1$ for all $x,x'\in\Omega$ and displacements $u$ and that $S^-_1>-1$ can be chosen arbitrarily close to $-1$. \newline
The fact that such a cutoff has to be introduced explicitly in the first place is a consequence of the physically undesirable behavior of the model under compression. The strain is capped at $-1$, limiting the material's ability to resist compression. Furthermore, the equations are such that no damage can occur from it. In practice this is mitigated either by penalization terms in the form of short-range forces counteracting inter-penetration \cite{SillMeshFree, MACEK20071169, PARKS2008777} acting on particles whose distance fall beneath a given threshold, or by reformulations of the bond strain itself \cite{TupekRadovitzky2014} solving the issue on the level of the continuous equations. Both remedies are constitutive rather than analytical in nature, and a consolidated treatment within the present class of models is, to our knowledge, not available. Therefore, we regard the question as outside the scope of this paper. \newline
We note that the necessity of such a modification is already visible from a mathematical view in the well-posedness theory of the model used here in \cite{WP_FRAC}. The cutoff of $g$ below $S^-_1$ is not merely a modeling convenience, rather, since the deformed bond direction degenerates as $\mathcal{S} \searrow -1$, with derivative of order $\|x'-x+u(x')-u(x)\|^{-1}$, a force scalar that does not vanish in this limit causes the proofs for the peridynamic operator to be Lipschitz continuous in the displacement $\mathbf{u}$ as given here to fail, as the change of the direction of the bond-forces $e$ no longer linearly correlates with the norm of the displacement. Following this interpretation, the mathematical analysis of the bond-breakage model employed here senses that there is an issue with the constitutive behavior in compression from a purely formal analysis.

\end{enumerate}
We note that we are not investigating the limit as $S^-_0,S^-_1 \searrow -1$ or $S^+_0 \rightarrow S^+_1$ and instead view the relaxed model not as an approximation but as an alternative to the steep cutoff model used in \cite{SillMeshFree}. Again, use of such models with a continuous cutoff in $\mu$ have been found to be useful in practice by themselves, e.g.  \cite{NIAZI2021102855}.

\label{def:constdisc}
\begin{enumerate}
    \item We construct the points with respect to which we want to formulate the mesh-free discrete problems as well as perform one-point quadrature.
    \begin{enumerate}
        \item We subdivide $\mathbb{R}^d$ for $d\in\{2,3\}$ into cubes/squares $(B_i)_{i\in \mathbb{Z}^d}$ of equal side length $\kappa>0$, with centers $x_i = \kappa i + \vec{o}_\kappa$ with $i \in \mathbb{Z}^d$ and some $\vec{o}_\kappa \in \mathbb{R}^d$. 
        \item We define $\Omega_i := \Omega \cap B_i$ for $i\in \mathbb{Z}^d$ if $\operatorname{vol}(\Omega \cap B_i)> 0$, and define the resulting index set of all such $i$ as $I^\kappa$.
        \item For notational simplicity we define $V_i := \operatorname{vol}(\Omega_i)$.
    \end{enumerate}
    \item The discrete bond stretch function for $i\not=j$, given by $\mathcal{S}^{ij}: (\mathbb{R}^d)^{I_\kappa}\rightarrow \mathbb{R}$ with $\mathcal{S}^{ij}(\vec{u}^\kappa) = \tfrac{\|\vec{u}^\kappa_j-\vec{u}^\kappa_i+x_j-x_i\|_2}{\|x_j-x_i\|_2}-1$.
    \item The discrete direction function $e^{ij}: (\mathbb{R}^d)^{I_\kappa}\rightarrow \mathbb{R}^d$ with $e^{ij}(\vec{u}^\kappa) = \tfrac{\vec{u}^\kappa_j-\vec{u}^\kappa_i+x_j-x_i}{\|\vec{u}^\kappa_j-\vec{u}^\kappa_i+x_j-x_i\|_2}$ if $\vec{u}_j^\kappa -\vec{u}_i^\kappa -  x_i + x_j \not=0$ and $0$ otherwise. Again, we call a bond $\zeta^{ij} = x_j-x_i$ at $x_i$ for a given discrete displacement $\vec{u}^\kappa$ and base point $x_i$ sub-critical if $\mathcal{S}^{ij}(\vec{u}^\kappa)< S^-_1$ and degenerate if $\mathcal{S}^{ij}(\vec{u}^\kappa) = -1$. 
    \item We introduce the function space $L^{\infty}_{\mathrm{ptw}}(A, B)$ for measurable Banach spaces $A$ and $B$, by defining 
\begin{equation*}
    L^{\infty}_{\mathrm{ptw}}(A, B) := \{ f: A \rightarrow B : f \text{ measurable}, \|f\|_{\text{sup}} := \sup_{x\in A}\|f(x)\|_B < \infty\},
\end{equation*}
with the $\|\cdot\|_{\text{sup}}$ norm.  This norm turns the space $L^\infty_{\mathrm{ptw}}$ into a Banach space.\par

    \item The discrete bond density function $\mathbf{f}^{ij}: L^\infty_{\text{ptw}}([-T,0], (\mathbb{R}^d)^{I^\kappa})\rightarrow \mathbb{R}^d$ and the corresponding discrete non-local operator $\vec{F}_\kappa: L^\infty_{\text{ptw}}([-T, 0], (\mathbb{R}^d)^{I_\kappa}) \rightarrow (\mathbb{R}^d)^{I_\kappa}$
    \begin{equation*}
        (\vec{F}_\kappa(\vec{\mathbf{u}}^\kappa))_i = \sum_{i\not=j} V_j\underbrace{\omega_\delta(\|x_j-x_i\|_2)g(\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(0)))\mu\Big(\sup_{-T\leq s\leq 0}\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(s))\Big)e^{ij}(\vec{\mathbf{u}}^\kappa(0))}_{=:\vec{\mathbf{f}}^{ij}(\vec{\mathbf{u}}^\kappa)}.
    \end{equation*}
    Again, the value of $\vec{F}_\kappa(\vec{\mathbf{u}}^\kappa)$ does not depend on the value of $e^{ij}$ for sub-critical bonds including degenerate bonds due to $g(\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(0))) = 0$. We will use this degree of freedom in the proofs below to eliminate the problem of degenerate and sub-critical bonds appearing in the discrete formulation.
    \end{enumerate}

\begin{align*}
    &\mathcal{K}_\kappa: (\mathbb{R}^d)^{I^\kappa} \rightarrow L^\infty(\Omega)^d, \ \ \vec{u} \mapsto (x\mapsto \sum_{i\in I^\kappa} \vec{u}_i \chi_{\Omega_i}(x) ), \\
    &\mathcal{P}_\kappa:  L^\infty(\Omega)^d \rightarrow (\mathbb{R}^d)^{I^\kappa}, {u}\mapsto \Big(\frac{1}{V_i} \int_{\Omega_i} {u}(x) \ \mathbf{d} x\Big)_{i\in I^\kappa}
\end{align*}

\label{ass:numconv}
    \begin{enumerate}
        \item $\omega_\delta: (0,\infty) \rightarrow \mathbb{R}_{\geq 0}$ measurable, non-increasing, vanishing for arguments greater than $\delta>0$, as well as the integrability condition,
        \begin{equation}\label{eqn:boundcond}
            \int_{B_\delta(0)} \frac{\omega_\delta(\|\zeta\|_2)}{\|\zeta\|_2}\ \mathbf{d} \zeta=:\mathcal{L} < \infty.
        \end{equation}
        \item $\rho>0$ constant.
        \item For the chosen sequence of $\kappa_n \searrow 0 $, we require
        \begin{enumerate}
            \item $\|\mathcal{K}_{\kappa_{n}} \vec{u}_0^{\kappa_n} - u_0\|_{L^\infty(\Omega)^d} \xrightarrow{n \rightarrow \infty} 0$, $\|\mathcal{K}_{\kappa_n} \vec{v}_0^{\kappa_n} - v_0\|_{L^\infty(\Omega)^d} \xrightarrow{n \rightarrow \infty} 0$.
            \item The discrete external body forces $\vec{\mathbf{b}}_{\kappa_n}\in C^0([0,T], (\mathbb{R}^d)^{I^\kappa})$, have to fulfill 
        \begin{equation*}
            \|\mathcal{K}_{\kappa_{n}}\vec{\mathbf{b}}_{\kappa_n} - \mathbf{b}\|_{C^0([0,T], L^\infty(\Omega)^d)} \xrightarrow[]{\kappa \searrow 0}0.
        \end{equation*}
        \end{enumerate}
    \end{enumerate}

\label{lemm:unifbndinteg} For all $i\in I^\kappa$ and $x\in \Omega_i$,
\begin{align*}
        0\leq \sum_{j\not=i} \int_{\Omega_j}\frac{\omega_\delta(\|x_j-x_i\|_2)}{\|x'-x\|_2} \ \mathbf{d} x' \leq \mathcal{L}^{\text{discr}},\\
        0\leq \sum_{j\not=i} V_j \frac{\omega_\delta(\|x_j-x_i\|_2)}{\|x_j-x_i\|_2}\leq \mathcal{L}^{\text{discr}},
\end{align*}
for a constant $\mathcal{L}^{\text{discr}}>0$ for all $\delta/\sqrt{d}> \kappa>0$.

This follows from 
    \begin{align}\label{eqn:bndnorm}
        \|x'-x\|_2 &\leq 2\tfrac{\sqrt{d}}{2}\kappa + \|x_i - x_j\|_2 \\
        &\leq (\sqrt{d} +1) \|x_i-x_j\|_2 \nonumber.
    \end{align}
    for all $x\in \Omega_i$, $x' \in \Omega_j$ with $i\not=j$, using the change of variables formula and Assumptions \ref{ass:numconv}, in particular, the monotonicity of $\omega_\delta$ and (\ref{eqn:boundcond}),
    \begin{align*}
        0&\leq \sum_{j\not=i} V_j \frac{\omega_\delta(\|x_j-x_i\|_2)}{\|x_j-x_i\|_2} \leq (\sqrt{d}+1)\sum_{j\not=i}\int_{\Omega_j} \frac{\omega_\delta(\|x_j-x_i\|_2)}{\|x'-x\|_2} \ \mathbf{d} x' \\
        &\leq (\sqrt{d}+1)^d\int_{B_{(\sqrt{d}+1)\delta}(x)} \frac{\omega_\delta(\tfrac{1}{\sqrt{d}+1}\|x'-x\|_2)}{\frac{1}{\sqrt{d}+1}\|x'-x\|_2} \frac{1}{(\sqrt{d}+1)^d}\ \mathbf{d} x'  \leq (\sqrt{d}+1)^d\mathcal{L}
    \end{align*}

\label{prop:LScontdiscrrhs} \newline
    Let $\vec{\mathbf{u}},\vec{\mathbf{v}}\in L^\infty_{\text{ptw}}([-T,0],(\mathbb{R}^d)^{I^\kappa})$, then
    \begin{equation*}
        \|\vec{F}_\kappa(\vec{\mathbf{u}}) - \vec{F}_\kappa(\vec{\mathbf{v}})\|_{\infty} \leq L_{\vec{F}}\|\vec{\mathbf{u}}-\vec{\mathbf{v}}\|_{L^\infty_{\text{ptw}}([-T,0], (\mathbb{R}^d)^{I^\kappa})} 
    \end{equation*}
    with $L_{\vec{F}}>0$ independent of $\delta/\sqrt{d}> \kappa > 0$.

This result follows similarly to how the Lipschitz continuity was obtained for the continuous operator $F$ in \cite{WP_FRAC}, Lemma 1. Since $g,\mu$ were not changed by the discretization, their Lipschitz constants are also unchanged. \par
Let $i\in I^\kappa$, then
\begin{align*}
    (\vec{F}_\kappa(\vec{\mathbf{u}}) - \vec{F}_\kappa(\vec{\mathbf{v}}))_i &=         \sum_{i\not=j} V_j{\omega_\delta(\|x_j-x_i\|_2)g(\mathcal{S}^{ij}(\vec{\mathbf{u}} (0)))\mu\Big(\sup_{-T\leq s\leq 0}\mathcal{S}^{ij}(\vec{\mathbf{u}} (s))\Big)e^{ij}(\vec{\mathbf{u}} (0))} \\
   &\quad -\sum_{i\not=j} V_j{\omega_\delta(\|x_j-x_i\|_2)g(\mathcal{S}^{ij}(\vec{\mathbf{v}} (0)))\mu\Big(\sup_{-T\leq s\leq 0}\mathcal{S}^{ij}(\vec{\mathbf{v}} (s))\Big)e^{ij}(\vec{\mathbf{v}} (0))}.
\end{align*}
To deal with these terms, we first find
\begin{equation}
\label{eqn:bndonsemdiscrS}    |\mathcal{S}^{ij}(\vec{\mathbf{u}} (t))-\mathcal{S}^{ij}(\vec{\mathbf{v}} (t))| \leq\tfrac{\sqrt{d}}{\|x_j-x_i\|_2}\Big(\|\vec{\mathbf{u}} _i(t) - \vec{\mathbf{v}} _i(t)\|_\infty + \|\vec{\mathbf{u}} _j(t) - \vec{\mathbf{v}} _j(t)\|_\infty\Big),
\end{equation}
as well as, assuming non-degenerate bonds for both $\mathbf{u}(t)$ and $\mathbf{v}(t)$,
\begin{equation}\label{eqn:bndonsemdiscre}
\begin{aligned}
    &\|e^{ij}(\vec{\mathbf{u}}(t))-e^{ij}(\vec{\mathbf{v}}(t))\|_\infty\\
    &\leq \frac{1}{\|\vec{\mathbf{u}}_j(t)-\vec{\mathbf{u}}_i(t)+x_j-x_i\|_2}(\|\vec{\mathbf{u}}_j(t)-\vec{\mathbf{u}}_i(t)- \vec{\mathbf{v}}_j(t)+\vec{\mathbf{v}}_i(t)\|_\infty)\\
    &\quad+\|\vec{\mathbf{v}}_j(t)-\vec{\mathbf{v}}_i(t)+x_j-x_i\|_\infty\frac{\|\vec{\mathbf{u}}_j(t)-\vec{\mathbf{u}}_i(t)- \vec{\mathbf{v}}_j(t)+\vec{\mathbf{v}}_i(t)\|_2}{\|\vec{\mathbf{u}}_j(t)-\vec{\mathbf{u}}_i(t)+x_j-x_i\|_2 \|\vec{\mathbf{v}}_j(t)-\vec{\mathbf{v}}_i(t)+x_j-x_i\|_2}\\
    &\leq \frac{2\sqrt{d}}{\|\vec{\mathbf{u}}_j(t)-\vec{\mathbf{u}}_i(t)+x_j-x_i\|_2} \Big(\|\vec{\mathbf{u}}_j(t)- \vec{\mathbf{v}}_j(t)\|_\infty+\|\vec{\mathbf{v}}_i(t)-\vec{\mathbf{u}}_i(t)\|_\infty\Big) \\
    &= \frac{2\sqrt{d}}{(\mathcal{S}^{ij}(\vec{\mathbf{u}}(t))+1)\|x_j-x_i\|_2} \Big(\|\vec{\mathbf{u}}_j(t)- \vec{\mathbf{v}}_j(t)\|_\infty+\|\vec{\mathbf{v}}_i(t)-\vec{\mathbf{u}}_i(t)\|_\infty\Big).
\end{aligned}
\end{equation}
Note that for any $t\in [-T, 0]$ and $i\in I^\kappa$,
\begin{equation*}
    \|\vec{\mathbf{u}}_j(t)- \vec{\mathbf{v}}_j(t)\|_\infty \leq \|\vec{\mathbf{u}}(t)- \vec{\mathbf{v}}(t)\|_\infty \leq \|\vec{\mathbf{u}}(t)- \vec{\mathbf{v}}(t)\|_{L^\infty_{\text{ptw}}([-T,0], (\mathbb{R}^d)^{I^\kappa})}.
\end{equation*}
We now need to deal with sub-critical bonds in $\vec{\mathbf{v}}$, which we do by defining $e^{ij}_{\vec{b}}: (\mathbb{R}^d)^{I_\kappa}\rightarrow \mathbb{R}^d$ by
\begin{align*}
    e^{ij}_{\vec{b}}(\vec{a}) = \begin{cases}e^{ij}(\vec{a}) & \text{if } \mathcal{S}^{ij}(\vec{a})\geq S^-_1\\
    e^{ij}(\vec{b}) & \text{else,}
    \end{cases}
\end{align*}
for $\vec{b}, \vec{a} \in (\mathbb{R}^d)^{I^\kappa}$.
With this, we define
\begin{equation*}
    (\vec{F}_{\kappa,\vec{\mathbf{u}}^\kappa}(\vec{\mathbf{a}}^\kappa))_i = \sum_{i\not=j} V_j{\omega_\delta(\|x_j-x_i\|_2)g(\mathcal{S}^{ij}(\vec{\mathbf{a}}^\kappa(0)))\mu\Big(\sup_{-T\leq s\leq 0}\mathcal{S}^{ij}(\vec{\mathbf{a}}^\kappa(s))\Big)e^{ij}_{\vec{\mathbf{u}}^\kappa(0)}(\vec{\mathbf{a}}^\kappa(0))}.
\end{equation*}
We then obtain $\vec{F}_\kappa(\vec{\mathbf{a}}^\kappa) = \vec{F}_{\kappa, \vec{\mathbf{u}}^\kappa}(\vec{\mathbf{a}}^\kappa)$ for all $\vec{\mathbf{a}}^\kappa, \vec{\mathbf{u}}^\kappa \in C^0([-T,0], (\mathbb{R}^d)^{I^\kappa})$.\par
This then leads to, using $g^+:= \max(|S^-_0|,|S^+_0|)= \sup_{s\in \mathbb{R}} |g(s)|$,
\begin{align*}
        &\|(\vec{F}_\kappa(\vec{\mathbf{u}}) - \vec{F}_\kappa(\vec{\mathbf{v}}))_i\|_\infty=\|(\vec{F}_\kappa(\vec{\mathbf{u}}) - \vec{F}_{\kappa, \vec{\mathbf{u}}^\kappa}(\vec{\mathbf{v}}))_i\|_\infty \\
        &\leq \sum_{i\not=j} V_j\omega_\delta(\|x_j-x_i\|_2)|g(\mathcal{S}^{ij}(\vec{\mathbf{u}} (0)))-g(\mathcal{S}^{ij}(\vec{\mathbf{v}} (0)))|\\
        &\quad+g^+\sum_{i\not=j} V_j\omega_\delta(\|x_j-x_i\|_2)\Big|\mu\Big(\sup_{-T\leq s\leq 0}\mathcal{S}^{ij}(\vec{\mathbf{v}} (s))\Big)-\mu\Big(\sup_{-T\leq s\leq 0}\mathcal{S}^{ij}(\vec{\mathbf{u}} (s))\Big)\Big|\\
        &\quad+\sum_{i\not=j} V_j\omega_\delta(\|x_j-x_i\|_2)|g(\mathcal{S}^{ij}(\vec{\mathbf{u}} (0)))|\|e^{ij}(\vec{\mathbf{u}} (0))-e^{ij}_{\vec{\mathbf{u}}^\kappa(0)}(\vec{\mathbf{v}} (0))\|_\infty \\
        \intertext{Note that $|g(\mathcal{S}^{ij}(\vec{\mathbf{u}} (0)))|\|e^{ij}(\vec{\mathbf{u}} (0))-e^{ij}_{\vec{\mathbf{u}}^\kappa(0)}(\vec{\mathbf{v}} (0))\|_\infty$ is $0$ both if $\mathcal{S}^{ij}(\vec{\mathbf{v}}(0))\in [-1, S^-_1)$ or $\mathcal{S}^{ij}(\vec{\mathbf{u}}(0))\in [-1, S^-_1)$, leading us to globally apply the bound (\ref{eqn:bndonsemdiscre}) with $\mathcal{S}^{ij}(\vec{\mathbf{u}}(0))\geq S^{-}_1$,}
        &\leq \sum_{i\not=j} 2\ell\sqrt{d}V_j\tfrac{\omega_\delta(\|x_j-x_i\|_2)}{\|x_j-x_i\|_2}  \|(\vec{\mathbf{u}}  - \vec{\mathbf{v}} )(0)\|_\infty \\
        &\quad+ \sum_{i\not=j} 2\ell g^+\sqrt{d}V_j\tfrac{\omega_\delta(\|x_j-x_i\|_2)}{\|x_j-x_i\|_2} \Bigg(\sup_{-T\leq s\leq 0}\|(\vec{\mathbf{u}}  - \vec{\mathbf{v}} )(s)\|_\infty\Bigg) \\
        &\quad+ \sum_{i\not=j} 4 g^+\sqrt{d}V_j\tfrac{\omega_\delta(\|x_j-x_i\|_2)}{(S^-_1+1)\|x_j-x_i\|_2}  \|(\vec{\mathbf{u}}  - \vec{\mathbf{v}} )(0)\|_\infty \\
        &\leq 2\sqrt{d}(\ell + \ell g^+ + \tfrac{2g^+}{S^-_1+1})\mathcal{L}^{\text{discr}}\|\vec{\mathbf{u}}  - \vec{\mathbf{v}} \|_{L^\infty_{\text{ptw}}([-T,0], (\mathbb{R}^d)^{I^\kappa})},
\end{align*}
where $\mathcal{L}^{\text{discr}}>0$ comes from Lemma \ref{lemm:unifbndinteg}.

We repeat the proof of \cite{WP_FRAC}, Theorem 2. Beginning first by rewriting (\ref{eqn:semdiscreqred}) into an  integral equation, 
\begin{equation}
\label{eqn:semdiscrinteqred}
        \mathbf{u}_{Red}^\kappa(t) = \int_{0}^t\vec{G}_\kappa((\mathbf{u}_{Red}^\kappa)_s, s) \ \mathbf{d} s + \vec{u}_{0, Red}^\kappa 
\end{equation}
for all $t\in [0,T]$. The claim now follows from a standard application of a Picard iteration on $C^0([0,T], (\mathbb{R}^d)^{I^\kappa} \times (\mathbb{R}^d)^{I^\kappa})$ defined by
\begin{equation*}
    \mathbf{u}^0:\equiv \vec{u}^\kappa_{0,Red},\ \ \ \mathbf{u}^n(t) := \int_{0}^t \vec{G}_\kappa((\mathbf{u}^{n-1})_s, s) \ \mathbf{d} s+\vec{u}^\kappa_{0,Red}\text{, for } n\geq 1.
\end{equation*}
This yields the claim through (\ref{eqn:LSG}) and
\begin{equation*}
    \|\Phi_s - \Psi_s\|_{L^\infty_{\text{ptw}}([-T,0], (\mathbb{R}^{d})^{I^\kappa}\times (\mathbb{R}^{d})^{I^\kappa})} \leq \|\Phi - \Psi\|_{C^0([0,T], (\mathbb{R}^{d})^{I^\kappa}\times (\mathbb{R}^{d})^{I^\kappa})}
\end{equation*}
dealing with the time dependence of the first argument for all $s\in [0,T]$. All these bounds then lead to the usual bounds, the latter obtained through induction,
\begin{equation*}
    \|\mathbf{u}^1(t) -\mathbf{u}^0(t) \|_{\infty} \leq Mt, \ \ \ \|\mathbf{u}^{n}(t)-\mathbf{u}^{n-1}(t)\| \leq ML^{n-1}_{\vec{G}}\tfrac{t^n}{n!}, \text{ for } n\geq 2,
\end{equation*}
with $M:= L_{\vec{G}}\|\vec{u}^\kappa_{0,Red}\|_\infty + \|\vec{\mathbf{b}_\kappa}\|_{C^0([0,T],(\mathbb{R}^d)^{I^\kappa})}$. This proves that the $(\mathbf{u}^n)_{n\in \mathbb{N}_0}$ define a Cauchy sequence whose limit has to fulfill (\ref{eqn:semdiscrinteqred}).

\label{rm:partvolumeweights}
Practical simulations include quadrature weights $w_{ij}$ replacing the $\chi_{[0,\delta]}(\|x_i-x_j\|_2)$ terms in $\omega_\delta(\|x_i-x_j\|_2)$, allowing for a more desirable numerical convergence behavior (See \cite{ImprovOnePointQuadAlgs, Seleson2018, Scabbia2023, LIU2024109115, TRASK2019151}). Then, $\omega_\delta(\|x_i-x_j\|_2) = \chi_{[0,\delta]}(\|x_i-x_j\|_2)\bar{\omega}(\|x_i-x_j\|_2)$ for some non-increasing $\bar{\omega}: (0,\infty) \rightarrow \mathbb{R}_{\geq 0}$ with $\omega_\delta \equiv \bar{\omega}$ on $(0,\delta]$ becomes $\omega^{ij}_\delta = w_{ij}\bar{\omega}(\|x_i-x_j\|_2)$. Including these weights does not cause significant theoretical problems for the results in this paper, as long as they fulfill the following assumptions taken from \cite{pflug2026convergencediscretizedlinearstatic}, for all $i,j\in I^\kappa$,
\begin{assumptions}[Assumptions on Partial Area Weights]\label{ass:quadweights}
\begin{enumerate}
    \item If $\|x_i-x_j\|_2 \geq \delta + \sqrt{d}\frac{\kappa}{2}$, then $w_{ij} = 0$.
    \item If $\|x_i-x_j\|_2 \leq \delta - \sqrt{d}\frac{\kappa}{2}$, then $w_{ij} = 1$.
    \item $0\leq w_{ij} \leq 1$.
    \item $w_{ij} = w_{ji}$.
\end{enumerate}
\end{assumptions}
Using these assumptions, Lemma \ref{lemm:unifbndinteg} and Lemma \ref{lemm:discrweighterrbnd} below can easily be adapted to include these terms. Rigorous proofs are given in the Appendix in Lemma \ref{lemm:alt34weights} and \ref{lemm:alt39weights}, respectively.
Note that requirements 1 and 2 merely ensure that if the $B_i$ do not intersect the horizon, or if it is fully inside, implied by its distance to $x_i$ alone, the weights have to be chosen to reflect this.

\label{ass:quadweights}
\begin{enumerate}
    \item If $\|x_i-x_j\|_2 \geq \delta + \sqrt{d}\frac{\kappa}{2}$, then $w_{ij} = 0$.
    \item If $\|x_i-x_j\|_2 \leq \delta - \sqrt{d}\frac{\kappa}{2}$, then $w_{ij} = 1$.
    \item $0\leq w_{ij} \leq 1$.
    \item $w_{ij} = w_{ji}$.
\end{enumerate}

\label{lemm:auxbnd} Let $u\in L^\infty(\Omega)^d$, $\vec{u}\in (\mathbb{R}^d)^{I^\kappa}$, $i,j \in I^\kappa$ with $i\not=j$, then for almost all $x\in \Omega_i$ and almost all $x' \in \Omega_j$,
\begin{align}
\label{eqn:bndonSdiff}
    |\mathcal{S}^{ij}(\vec{u}) - \mathcal{S}(u, x',x)| & \leq \begin{cases}
        \frac{\sqrt{d}}{\|x'-x\|_2}( 2\|\mathcal{K}_\kappa\vec{u}-u\|_{L^\infty(\Omega)^d} + (\mathcal{S}^{ij}(\vec{u})+2)\|x_j-x_i-x'+x\|_\infty) \\
        \frac{\sqrt{d}}{\|x_j-x_i\|_2}( 2\|\mathcal{K}_\kappa\vec{u}-u\|_{L^\infty(\Omega)^d} + (\mathcal{S}({u},x',x)+2)\|x_j-x_i-x'+x\|_\infty),
    \end{cases}
\end{align}
where case brackets without conditions on the right signify that all cases hold simultaneously.\par
Similarly, for $\vec{u}$ with $\vec{u}_i-\vec{u}_j + x_i -x_j\not= 0$ and $u(x')-u(x)+x'-x \not= 0$,
\begin{align}\label{eqn:bndresesem}
    |e({u},x',x) - e^{ij}(\vec{u})| \leq 
    \tfrac{2\sqrt{d}}{(\mathcal{S}({u},x',x)+1)\|x'-x\|_2}\Big(2 \|\mathcal{K}_\kappa\vec{u} - u\|_{L^\infty(\Omega)^d} + \|x-x_i-x'+x_j\|_\infty\Big).
\end{align}
For $\mathbf{u}\in C^0([-T,0], L^\infty(\Omega)^d)$, $\vec{\mathbf{u}}\in C^0([-T,0], (\mathbb{R}^d)^{I^\kappa})$, we have for almost all $x,x'$,
\begin{equation}\label{eqn:BndResultMu}
\begin{aligned}
    &\Big|{\mu\Big(\operatorname*{ess\,sup}_{-T\leq s \leq 0} \mathcal{S}([\Gamma\mathbf{u}](s), x', x)\Big)}_{} -{\mu\Big(\sup_{-T\leq s \leq 0} \mathcal{S}^{ij}(\vec{\mathbf{u}}(s))\Big)}_{}\Big|\\
    &\leq \Big((\sqrt{d}+1)\tfrac{\sqrt{d}\ell}{\|x'-x\|_2}\Big)( 2\|\mathcal{K}_\kappa\vec{\mathbf{u}}-\mathbf{u}\|_{C^0([-T,0],L^\infty(\Omega)^d)} + (S^+_1+2)\|x_j-x_i-x'+x\|_\infty) .
\end{aligned}
\end{equation}
Similarly, we have,
\begin{equation}\label{eqn:BndResultscalarlaw}
\begin{aligned}
    &|g(\mathcal{S}(u, x', x)) -g(\mathcal{S}^{ij}(\vec{{u}}))|\\
    &\leq \begin{cases}
        \frac{\ell\sqrt{d}}{\|x'-x\|_2}( 2\|\mathcal{K}_\kappa\vec{u}-u\|_{L^\infty(\Omega)^d} + (S^+_1+2)\|x_j-x_i-x'+x\|_\infty) \\
        \frac{\ell\sqrt{d}}{\|x_j-x_i\|_2}( 2\|\mathcal{K}_\kappa\vec{u}-u\|_{L^\infty(\Omega)^d} + (S^+_1+2)\|x_j-x_i-x'+x\|_\infty).
    \end{cases}\\
    &\leq\frac{\ell\sqrt{d}(\sqrt{d}+1)}{\|x'-x\|_2}( 2\|\mathcal{K}_\kappa\vec{u}-u\|_{L^\infty(\Omega)^d} + (S^+_1+2)\|x_j-x_i-x'+x\|_\infty).
\end{aligned}
\end{equation}

For the first claim, we see that
\begin{align*}
    |\mathcal{S}^{ij}(\vec{u}) - \mathcal{S}(u, x',x)| &= \Big|\tfrac{\|\vec{u}_j-\vec{u}_i+x_j-x_i\|_2}{\|x_j-x_i\|_2} - \tfrac{\|u(x')-u(x)+x'-x\|_2}{\|x'-x\|_2}\Big|\\
     &\leq \tfrac{1}{\|x_j-x_i\|_2}\Big|\|\vec{u}_j-\vec{u}_i+x_j-x_i\|_2- \|u(x')-u(x)+x'-x\|_2\Big|\\
     &\quad + \|u(x')-u(x)+x'-x\|_2 \Big|\tfrac{1}{\|x'-x\|_2} - \tfrac{1}{\|x_j-x_i\|_2}\Big| \\
     &\leq \tfrac{1}{\|x_j-x_i\|_2} \Big(\|\mathcal{K}_\kappa\vec{u}(x')-u(x')\|_2 + \|\mathcal{K}_\kappa\vec{u}(x)-u(x)\|_2 + \|x'-x_j-x+x_i\|_2 \\
     & \quad + \tfrac{\|u(x')-u(x)+x'-x\|_2}{\|x'-x\|_2} \|x'-x_j-x+x_i\|_2\Big) \\
     &\leq \tfrac{\sqrt{d}}{\|x_j-x_i\|_2} \Big(2\|\mathcal{K}_\kappa\vec{u}-u\|_{L^\infty(\Omega)^d} + (\mathcal{S}(u, x',x) +2) \|x'-x_j-x+x_i\|_\infty\Big).
\end{align*}
The other bound is derived similarly. For the differences of the $e$ terms, assuming the bond $x'-x$ is non-degenerate for $u$ in $x$, similarly that the bond $x_j-x_i$ is non-degenerate for $\vec{u}$ in $x_i$, we have
\begin{equation}
\begin{aligned}
     \|e({u},x',x) - e^{ij}(\vec{u})\|_\infty &\leq \Big\| \tfrac{{u}(x')-{u}(x)+x'-x}{\|{u}(x')-{u}(x)+x'-x\|_2}-\tfrac{\vec{u}_j-\vec{u}_i+x_j-x_i}{\|\vec{u}_j-\vec{u}_i+x_j-x_i\|_2}\Big\|_\infty\\
     &\leq \tfrac{\|{u}(x')-\vec{u}_j\|_\infty + \|{u}(x)-\vec{u}_i\|_\infty+\|x'-x-x_j+x_i\|_\infty}{\|{u}(x')-{u}(x)+x'-x\|_2} \\
     & + \sqrt{d}\|\vec{u}_j-\vec{u}_i +x_j-x_i\|_\infty \tfrac{\|{u}(x')-\vec{u}_j\|_\infty + \|{u}(x)-\vec{u}_i\|_\infty+\|x'-x-x_j+x_i\|_\infty}{\|\vec{u}_j-\vec{u}_i +x_j-x_i\|_2 \|{u}(x')-{u}(x)+x'-x\|_2} \\
     &\leq 2\sqrt{d}\tfrac{2 \|{u} -\mathcal{K}_\kappa \vec{u}\|_{L^\infty(\Omega)^d} + \|x'-x-x_j+x_i\|_\infty}{\|{u}(x')-{u}(x)+x'-x\|_2} \\
    &\leq \tfrac{2\sqrt{d}}{(\mathcal{S}({u},x',x)+1)\|x'-x\|_2}(2 \|{u} -\mathcal{K}_\kappa \vec{u}\|_{L^\infty(\Omega)^d} + \|x'-x-x_j+x_i\|_\infty).
    \end{aligned}
\end{equation}
For the $\mu$ terms, we see that
\begin{align*}
&\Big|\underbrace{\mu\Big(\operatorname*{ess\,sup}_{-T\leq s \leq 0} \mathcal{S}([\Gamma\mathbf{u}](s), x', x)\Big)}_{=:A} -\underbrace{\mu\Big(\sup_{-T\leq s \leq 0} \mathcal{S}^{ij}(\vec{\mathbf{u}}(s))\Big)}_{=:B}\Big|\\
\intertext{on which we apply the bound  (\ref{eqn:bndonSdiff}) after using the Lipschitz continuity of $\mu$. The values of $A$ and $B$ are used to choose the fitting case to bound  either $\mathcal{S}(u,x',x)$ or $\mathcal{S}^{ij}(\vec{\mathbf{u}})$ from above,}
&\leq \begin{cases}
    0 & A = B= 0\\
    \frac{\sqrt{d}\ell}{\|x'-x\|_2}( 2\operatorname*{ess\,sup}_{-T\leq s \leq 0}\|\mathcal{K}_\kappa\vec{\mathbf{u}}(s)-\mathbf{u}(s)\|_{L^\infty(\Omega)^d} + (S^+_1+2)\|x_j-x_i-x'+x\|)  & B >0 \\
    \frac{\sqrt{d}\ell}{\|x_j-x_i\|_2}( 2\operatorname*{ess\,sup}_{-T\leq s \leq 0}\|\mathcal{K}_\kappa\vec{\mathbf{u}}(s)-\mathbf{u}(s)\|_{L^\infty(\Omega)^d} + (S^+_1+2)\|x_j-x_i-x'+x\|)  &  A>0
\end{cases} 
\end{align*}
since $A=0 \Leftrightarrow \operatorname*{ess\,sup}_{-T\leq s \leq 0} \mathcal{S}([\Gamma\mathbf{u}](s), x', x) \geq S^+_1$ as well as $B=0 \Leftrightarrow \sup_{-T\leq s \leq 0} \mathcal{S}^{ij}(\vec{\mathbf{u}}(s)) \geq S^+_1$. We also made use of 
\begin{align*}
    \Big| \operatorname*{ess\,sup}_{-T\leq s \leq 0} \mathcal{S}([\Gamma\mathbf{u}](s), x', x)  - \sup_{-T\leq s \leq 0} \mathcal{S}^{ij}(\vec{\mathbf{u}}(s)) \Big| &\leq \operatorname*{ess\,sup}_{-T\leq s \leq 0} |\mathcal{S}(\mathbf{u}(s), x', x) - \mathcal{S}^{ij}(\vec{\mathbf{u}}(s))|
\end{align*}
implied by the continuity of $\mathbf{u}$ and $\vec{\mathbf{u}}$ in $t \in [0,T]$.
The inequality (\ref{eqn:BndResultMu}) then follows from  $\|x-x'\| \leq (\sqrt{d} +1)\|x_i-x_j\|$ for $i\not=j$ and $x\in\Omega_i$, $x'\in\Omega_j$. \par
We apply similar reasoning to obtain
\begin{align*}
&\Big|\underbrace{g(\mathcal{S}(u, x', x))}_{=:A} -\underbrace{g( \mathcal{S}^{ij}(\vec{u})}_{=:B})\Big|\\
\intertext{we apply the Lipschitz continuity of $g$, and again select the suitable branch from (\ref{eqn:bndonSdiff})}
&\leq \begin{cases}
    0 & A = B= 0\\
    \frac{\sqrt{d}\ell}{\|x'-x\|_2}( 2\operatorname*{ess\,sup}_{-T\leq s \leq 0}\|\mathcal{K}_\kappa\vec{\mathbf{u}}(s)-\mathbf{u}(s)\|_{L^\infty(\Omega)^d} + (S^+_1+2)\|x_j-x_i-x'+x\|)  & B \not=0 \\
    \frac{\sqrt{d}\ell}{\|x_j-x_i\|_2}( 2\operatorname*{ess\,sup}_{-T\leq s \leq 0}\|\mathcal{K}_\kappa\vec{\mathbf{u}}(s)-\mathbf{u}(s)\|_{L^\infty(\Omega)^d} + (S^+_1+2)\|x_j-x_i-x'+x\|)  &  A\not=0.
\end{cases} 
\end{align*}

\label{lemm:shellbounds}
    Let $\omega_\delta: (0,\infty) \rightarrow \mathbb{R}_{\geq 0}$ be as required in Assumptions \ref{ass:numconv}. We then obtain for any $s > 0$,
    \begin{enumerate}
        \item If $r \geq 2s$ and $|l - r| \leq s$, we have
        \begin{equation*}
            |\omega_\delta(l) - \omega_\delta(r)| \leq \omega_\delta(r - s) - \omega_\delta(r + s)
        \end{equation*}
        \item We have
        \begin{equation*}
            \int_{\|\zeta\|_2 \geq 2s} \omega_\delta(\|\zeta\|_2 - s) - \omega_\delta(\|\zeta\|_2 + s) \ \mathbf{d} \zeta \leq 3\cdot2^{d-1} s \mathcal{L}
        \end{equation*}
        \item For all $r>0$, 
        \begin{equation*}
            \int_{B_r(0)} \omega_\delta(\|\zeta\|_2) \ \mathbf{d} \zeta \leq r \mathcal{L}.
        \end{equation*}
    \end{enumerate}

Claim 1 follows directly from $\omega_\delta$ non-increasing as required in Assumptions \ref{ass:numconv}, as $l,r \in [r-s, r+s]$. \newline
    Claim 2 follows by using polar coordinates and using $c_d := \operatorname{vol}_{d-1}(S^{d-1})$,
    \begin{align*}
        &\int_{\|\zeta\|_2 \geq 2s} \omega_\delta(\|\zeta\|_2 - s) - \omega_\delta(\|\zeta\|_2 + s) \ \mathbf{d} \zeta \\
        &= \int_{2s}^\infty \int_{S^{d-1}} (\omega_\delta(r -s) - \omega_\delta(r+s)) r^{d-1}\ \mathbf{d} r \ \mathbf{d} \mathcal{H}^{d-1}(\zeta) \\
        &= c_d \int_{2s}^\infty (\omega_\delta(r -s) - \omega_\delta(r+s)) r^{d-1}\ \mathbf{d} r
        \intertext{splitting this integral and shifting the domains by $s$ via substitution yields}
        &= c_d \int_{s}^\infty \omega_\delta(t) (t+s)^{d-1}\ \mathbf{d} t  - c_d \int_{3s}^\infty \omega_\delta(t) (t-s)^{d-1}\ \mathbf{d} t \\
        &=  c_d \int_{s}^{3s} \omega_\delta(t) (t+s)^{d-1}\ \mathbf{d} t  + c_d \int_{3s}^\infty \omega_\delta(t) ((t+s)^{d-1} -(t-s)^{d-1})\ \mathbf{d} t 
    \end{align*}
    We then obtain for $t\in [s, 3s]$, that $(t+s)^{d-1} \leq 2^{d-1} t^{d-1} \leq 3 \cdot 2^{d-1} s t^{d-2}$, further for $t\geq 3s$, using the mean value theorem
    \begin{align*}
        (t+s)^{d-1} -(t-s)^{d-1} \leq 2(d-1) s (t+s)^{d-2} \leq  2(d-1) s (4/3)^{d-2} t^{d-2}
    \end{align*}
    using $d\geq 2$ and $s/t \leq 1/3$.  Both these inequalities then yield
    \begin{align*}
        &c_d \int_{s}^{3s} \omega_\delta(t) (t+s)^{d-1}\ \mathbf{d} t  + c_d \int_{3s}^\infty \omega_\delta(t) ((t+s)^{d-1} -(t-s)^{d-1})\ \mathbf{d} t \\
        &\leq s \max(2(d-1)(4/3)^{d-2}, 3\cdot 2^{d-1}) c_d\int_s^\infty \omega_\delta(t)   t^{d-2}\ \mathbf{d} t \\
        &\leq 3\cdot 2^{d-1} s \int_{\|\zeta\|\geq s}\frac{\omega_\delta(\|\zeta\|_2)}{\|\zeta\|_2} \ \mathbf{d} \zeta \leq 3\cdot 2^{d-1} s  \mathcal{L}
    \end{align*}
    Claim 3 follows immediately from $\|\zeta\|_2 \leq r$ for $\zeta \in B_r(0)$ and therefore $1 = \|\zeta\|_2/\|\zeta\|_2 \leq r/\|\zeta\|_2$ in the integrand for almost all $\zeta \in B_r(0)$.

\label{lemm:discrweighterrbnd} Let $i\in I^\kappa$, then, for all $x\in \Omega_i$,
\begin{equation*}
   \sum_{i\not=j}\int_{\Omega_j} |\omega_\delta(\|x_j-x_i\|_2)-\omega_\delta(\|x'-x\|_2)| \ \mathbf{d} x' \leq D_\kappa,
\end{equation*}
with $0<D_\kappa< \infty$ independent of $x$ and $i$ as well as $ O(\kappa) \ni D_\kappa \searrow 0$ as $\frac{\delta}{2\sqrt{d}}> \kappa \searrow 0$.

Set  $s:=\sqrt{d}\kappa$, $r(x'):=\|x'-x\|_2$ and $l(x'):=\|x_i-x_{j(x')}\|_2$, where $j(x')$ is the unique $j\in  \mathbb{Z}^d$ such that $x' \in B_j$. Then, Lemma \ref{lemm:shellbounds} yields using $|r(x') - l(x')| \leq s$ and $U := \Omega\backslash \Omega_i$,
\begin{align*}
    &\sum_{i\not=j}\int_{\Omega_j} |\omega_\delta(\|x_j-x_i\|_2)-\omega_\delta(\|x'-x\|_2)| \ \mathbf{d} x' \\
    &\leq\int_{U}|\omega_\delta(l(x'))-\omega_\delta(r(x'))| \ \mathbf{d} x' \\
    &\leq\int_{\|x'-x\|\geq 2s}|\omega_\delta(l(x'))-\omega_\delta(r(x'))| \ \mathbf{d} x'\\
    &\quad + \int_{x'\in U, \|x'-x\|\leq 2s}|\omega_\delta(l(x'))-\omega_\delta(r(x'))| \ \mathbf{d} x'
\end{align*}
We then have 
\begin{align*}
    &\int_{\|x'-x\|\geq 2s}|\omega_\delta(l(x'))-\omega_\delta(r(x'))| \ \mathbf{d} x' \\
    &\leq \int_{\|x'-x\|\geq 2s}\omega_\delta(r(x')-s)-\omega_\delta(r(x')+s) \ \mathbf{d} x' \\
    &\leq 3\cdot 2^{d-1} s \mathcal{L}
\end{align*}
as well as
\begin{align*}
    &\int_{x'\in U, \|x'-x\|\leq 2s}|\omega_\delta(l(x'))-\omega_\delta(r(x'))| \ \mathbf{d} x' \\
    &\leq \int_{x'\in U, \|x'-x\|\leq 2s}\omega_\delta(l(x'))+\omega_\delta(r(x')) \ \mathbf{d} x' \\
    &\leq 3s\mathcal{L}^{\text{discr}} + 2s \mathcal{L},
\end{align*}
due to $l(x') \leq 3s$ if $r(x') \leq 2s$, with Lemma \ref{lemm:unifbndinteg}. The claim now follows as $s = \sqrt{d}\kappa$.

\label{prop:discrrhserr}
Let $\mathbf{u}\in C^0([0,T], L^\infty(\Omega)^d)$ and $\vec{\mathbf{u}} \in C^0([0,T], (\mathbb{R}^d)^{I^\kappa})$, then, for all $t\in [0,T]$,
\begin{equation*}
    \|F(\mathbf{u}_t) - \mathcal{K}_\kappa \vec{F}_\kappa((\vec{\mathbf{u}})_t) \|_{L^\infty(\Omega)^d} \leq \beta \max_{0\leq s \leq t}\|\mathbf{u}(s) - \mathcal{K}_\kappa\vec{\mathbf{u}}(s)\|_{L^\infty(\Omega)^d} + \alpha_\kappa
\end{equation*}
for some $\alpha_\kappa, \beta \geq 0$, and \begin{equation*}
    O(\kappa) \ni \alpha_\kappa \xrightarrow[]{\kappa \searrow 0} 0,\ \ \ 0<\beta < \infty
\end{equation*}
for $\kappa \searrow 0$ and $\beta>0$ independent of  $0<\kappa< \delta/(2\sqrt{d})$ and $t\in [0,T]$.

Again, we now need to deal with sub-critical bonds first, which we do by defining $e^{ij}_{u}: (\mathbb{R}^d)^{I_\kappa}\times \Omega_j \times \Omega_i \rightarrow \mathbb{R}^d$ by
\begin{align*}
    e^{ij}_{u}(\vec{a},x',x) = \begin{cases}e^{ij}(\vec{a}) & \text{if } \mathcal{S}^{ij}(\vec{a})\geq S^-_1\\
    e(u,x',x) & \text{else,}
    \end{cases}
\end{align*}
for $\vec{a} \in (\mathbb{R}^d)^{I^\kappa}$ and $u \in L^\infty(\Omega)^d$.
With this, we also define for $x\in \Omega_i$ for all $i$,
\begin{align*}
    &(F_{\kappa,u}^{\text{discr}}(\vec{\mathbf{a}}^\kappa))(x) \\
    &= \int_\Omega \sum_{i\not=j}\chi_{\Omega_j}(x') {\omega_\delta(\|x_j-x_i\|_2)g(\mathcal{S}^{ij}(\vec{\mathbf{a}}^\kappa(0)))\mu\Big(\sup_{-T\leq s\leq 0}\mathcal{S}^{ij}(\vec{\mathbf{a}}^\kappa(s))\Big)e^{ij}_{u}(\vec{\mathbf{a}}^\kappa(0),x',x)} \ \mathbf{d} x'.
\end{align*}
We then obtain $\mathcal{K}_\kappa\vec{F}_\kappa(\vec{\mathbf{a}}^\kappa) = F_{\kappa,u}^{\text{discr}}(\vec{\mathbf{a}}^\kappa)$ for all $\vec{\mathbf{a}}^\kappa\in C^0([-T,0], (\mathbb{R}^d)^{I^\kappa})$ and $u \in L^\infty(\Omega)^d$.\par

    We pick an $i\in I^\kappa$, then for almost all $x\in \Omega_i$,
    \begin{align}
        &\|(F(\mathbf{u}_t) - \mathcal{K}_\kappa \vec{F}_{\kappa}((\vec{\mathbf{u}})_t)(x)\|_\infty= \|(F(\mathbf{u}_t) - (F_{\kappa,\mathbf{u}(t)}^{\text{discr}}((\vec{\mathbf{u}})_t))(x)\|_\infty\nonumber \\
        &\leq \Big\|\sum_{i\not=j} \int_{\Omega_j} \omega_\delta(\|x'-x\|_2)g(\mathcal{S}(\mathbf{u}(t), x', x))\mu\Big(\operatorname*{ess\,sup}_{0\leq s\leq t}\mathcal{S}([\Gamma\mathbf{u}](s), x', x) \Big)e(\mathbf{u}(t), x',x) \label{eqn:lastineq} \\
        &\phantom{=====}-\omega_\delta(\|x_j-x_i\|_2)g(\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(t)))\mu\Big(\sup_{0\leq s\leq t}\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(s))\Big)e^{ij}_{\mathbf{u}(t)}(\vec{\mathbf{u}}^\kappa(t),x',x) \ \mathbf{d} x'\Big\|_\infty \nonumber\\
        &\quad + \int_{\Omega_i}\|\omega_\delta(\|x'-x\|_2)g(\mathcal{S}(\mathbf{u}(t), x', x))\mu\Big(\operatorname*{ess\,sup}_{0\leq s\leq t}\mathcal{S}([\Gamma\mathbf{u}](s), x', x) \Big)e(\mathbf{u}(t), x',x) \|_\infty \ \mathbf{d} x'\nonumber
    \end{align}
We now see that for all $x\in \Omega_i$,
\begin{align*}
    &\int_{\Omega_i}\|\omega_\delta(\|x'-x\|_2)g(\mathcal{S}(\mathbf{u}(t), x', x))\mu\Big(\operatorname*{ess\,sup}_{0\leq s\leq t}\mathcal{S}([\Gamma\mathbf{u}](s), x', x) \Big)e(\mathbf{u}(t), x',x)\|_\infty \ \mathbf{d} x' \\
    &\leq \|\omega_\delta(\|\cdot\|_2)\|_{L^1(B_{\kappa\sqrt{d} }(0))} g^+ =: \alpha_1^\kappa 
\end{align*}
Since $\omega_\delta \in L^1(B_\delta(0))$, we see that $\alpha_1^\kappa \searrow 0$ for $\kappa \searrow 0$. With Lemma \ref{lemm:shellbounds} we see that $\alpha_1^\kappa \in O(\kappa)$. \par 


We then derive a bound for the other summand in (\ref{eqn:lastineq}), using Lemma \ref{lemm:unifbndinteg} and Lemma \ref{lemm:auxbnd}, 
\begin{align*}
    &\Big\|\sum_{i\not=j} \int_{\Omega_j} \omega_\delta(\|x'-x\|_2)g(\mathcal{S}(\mathbf{u}(t), x', x))\mu\Big(\operatorname*{ess\,sup}_{0\leq s\leq t}\mathcal{S}([\Gamma\mathbf{u}](s), x', x) \Big)e(\mathbf{u}(t), x',x) \\
    &\phantom{===}-\omega_\delta(\|x_j-x_i\|_2)g(\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(t)))\mu\Big(\max_{0\leq s\leq t}\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(s))\Big)e^{ij}_{\mathbf{u}(t)}(\vec{\mathbf{u}}^\kappa(t),x',x) \ \mathbf{d} x'\Big\|_\infty\\
    &\leq \Big\|\sum_{i\not=j} \int_{\Omega_j}  (\omega_\delta(\|x_j-x_i\|_2)-\omega_\delta(\|x'-x\|_2))g(\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(t)))\mu\Big(\max_{0\leq s\leq t}\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(s))\Big)e^{ij}_{\mathbf{u}(t)}(\vec{\mathbf{u}}^\kappa(t),x',x) \ \mathbf{d} x'\Big\|_\infty \\
    &\quad + \Big\|\sum_{i\not=j} \int_{\Omega_j}  \omega_\delta(\|x'-x\|_2)|g(\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(t)))-g(\mathcal{S}(\mathbf{u}(t), x', x))|\mu\Big(\max_{0\leq s\leq t}\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(s))\Big)e^{ij}_{\mathbf{u}(t)}(\vec{\mathbf{u}}^\kappa(t),x',x) \ \mathbf{d} x'\Big\|_\infty \\
    &\quad+ \Big\|\sum_{i\not=j} \int_{\Omega_j} \omega_\delta(\|x'-x\|_2)\mu\Big(\max_{0\leq s\leq t}\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(s))\Big)g(\mathcal{S}(\mathbf{u}(t), x', x))(e^{ij}_{\mathbf{u}(t)}(\vec{\mathbf{u}}^\kappa(t), x',x)-e(\mathbf{u}(t), x',x)) \ \mathbf{d} x'\Big\|_\infty \\
    &\quad+ \Big\|\sum_{i\not=j} \int_{\Omega_j} \omega_\delta(\|x'-x\|_2)g(\mathcal{S}(\mathbf{u}(t), x', x))\Big|\mu\Big(\max_{0\leq s\leq t}\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(s))\Big)\\
    &\phantom{========================00=}-\mu\Big(\operatorname*{ess\,sup}_{0\leq s\leq t}\mathcal{S}([\Gamma\mathbf{u}](s), x',x)\Big)\Big|e(\mathbf{u}(t), x',x)\ \mathbf{d} x' \Big\|_\infty \\
    \intertext{Again, by construction, $g(\mathcal{S}(\mathbf{u}(t), x', x))(e^{ij}_{\mathbf{u}(t)}(\vec{\mathbf{u}}^\kappa(t), x', x)-e(\mathbf{u}(t), x',x))$ is $0$ if $\mathcal{S}(\mathbf{u}(t), x', x) \in [-1, S^-_1)$ or $\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(t))\in [-1, S^-_1)$, so apply the bound (\ref{eqn:bndresesem}) with $\mathcal{S}(\mathbf{u}(t),x',x) \geq S^-_1$,}
    &\leq g^+ \Big\|\sum_{i\not=j}\int_{\Omega_j} |\omega_\delta(\|x_j-x_i\|_2)-\omega_\delta(\|x'-x\|)| \ \mathbf{d} x'\Big\|_{L^\infty(\Omega_i)^d}\\
    &\quad+\ell\sum_{i\not=j} \int_{\Omega_j}  \omega_\delta(\|x'-x\|_2)\frac{\sqrt{d}(\sqrt{d}+1)}{\|x'-x\|_2}( 2\|(\mathcal{K}_\kappa\vec{\mathbf{u}}-\mathbf{u})(t)\|_{L^\infty(\Omega)^d}\\
    &\phantom{===========================} + (S^+_1+2)\|x_j-x_i-x'+x\|_\infty)\ \mathbf{d} x' \\
    &\quad+ g^+\sum_{j\not=i} \int_{\Omega_j}\omega_\delta(\|x'-x\|) \tfrac{2\sqrt{d}}{(S^-_1+1)\|x'-x\|_2}\Big(2 \|(\mathcal{K}_\kappa\vec{\mathbf{u}} - \mathbf{u})(t)\|_{L^\infty(\Omega)^d}\\
    &\phantom{===========================}+ \|x-x_i-x'+x_j\|_\infty\Big) \ \mathbf{d} x' \\
    &\quad+\ell g^+ \sum_{j\not=i} \int_{\Omega_j}\omega_\delta(\|x'-x\|)\Big(\tfrac{(\sqrt{d}+1)\sqrt{d}}{\|x'-x\|_2}\Big)( 2\max_{0\leq s\leq t}\|(\mathcal{K}_\kappa \vec{\mathbf{u}} - \mathbf{u})(s)\|_{L^\infty(\Omega)^d}\\
    &\phantom{===========================}+ (S^+_1+2)\|x_j-x_i-x'+x\|_\infty)   \ \mathbf{d} x'\\
    &\leq  g^+ D_\kappa \\
    &\quad + \ell \sqrt{d}(\sqrt{d}+1) \mathcal{L} \Big(2\max_{0\leq s\leq t}\|(\mathcal{K}_\kappa \vec{\mathbf{u}} - \mathbf{u})(s)\|_{L^\infty(\Omega)^d} + (S^+_1+2){\kappa}\Big) \\
    &\quad + 2\sqrt{d}\tfrac{g^+}{(S^-_1+1)} \mathcal{L} \Big(2\max_{0\leq s\leq t}\|(\mathcal{K}_\kappa \vec{\mathbf{u}} - \mathbf{u})(s)\|_{L^\infty(\Omega)^d} + {\kappa}\Big) \\
    &\quad +  2\ellg^+ \sqrt{d}(\sqrt{d}+1)  \mathcal{L} \Big(\max_{0\leq s\leq t}\|(\mathcal{K}_\kappa \vec{\mathbf{u}} - \mathbf{u})(s)\|_{L^\infty(\Omega)^d} + \tfrac{1}{2}(S^+_1 + 2){\kappa}\Big),
\end{align*}
where we made use of 
\begin{equation*}
    \max_{-T\leq s\leq 0}\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(s))=  \operatorname*{ess\,sup}_{-T\leq s\leq 0}\mathcal{S}^{ij}(\vec{\mathbf{u}}^\kappa(s))
\end{equation*}
and
\begin{equation*}
    \operatorname*{ess\,sup}_{0\leq s \leq t}\|[\mathbf{u} - \mathcal{K}_\kappa\vec{\mathbf{u}}^{\kappa}](s)\|_{L^\infty(\Omega)^d} = \max_{0\leq s\leq t}\|[\mathbf{u} - \mathcal{K}_\kappa\vec{\mathbf{u}}^{\kappa}](s)\|_{L^\infty(\Omega)^d}
\end{equation*}
due to the continuity of $\mathbf{u}$ and $\mathcal{K}_\kappa\vec{\mathbf{u}}$ in $t\in[0,T]$.

\label{lemm:transport} Let $\vec{\mathbf{u}}\in C^1([0,T], (\mathbb{R}^d)^{I^\kappa})$, then $\mathcal{K}_\kappa\vec{\mathbf{u}} \in C^1([0,T], L^\infty(\Omega)^d)$ and
\begin{equation*}
    \tfrac{d}{dt}(\mathcal{K}_\kappa \vec{\mathbf{u}})(t) = \mathcal{K}_\kappa \dot{\vec{\mathbf{u}}}(t)
\end{equation*}
as well as
\begin{equation} \label{eqn:transp2}
    \mathcal{K}_\kappa \vec{\mathbf{u}}(t)- \mathcal{K}_\kappa {\vec{\mathbf{u}}}(0) = \int_{0}^t \mathcal{K}_\kappa \dot{\vec{\mathbf{u}}}(s) \ \mathbf{d} s,
\end{equation}
for all $t\in [0,T]$.

\label{theo:convsemidiscr}
    Let Assumptions \ref{ass:numconv} hold. Let $\kappa_n \searrow 0$ and $\vec{\mathbf{u}}^{\kappa_n}\in C^2([0,T], (\mathbb{R}^d)^{I^{\kappa_n}})$ be the solutions to the semi-discrete problem (\ref{eqn:semdiscrprobl}), as well as $\mathbf{u}\in C^2([0,T], L^\infty(\Omega)^d)$ the solution to the continuous problem (\ref{eqn:conteq}), then
    \begin{equation*}
        \|\mathbf{u} - \mathcal{K}_{\kappa_{n}}\vec{\mathbf{u}}^{\kappa_n}\|_{C^1([0,T], L^\infty(\Omega)^d)} \xrightarrow[]{n \rightarrow \infty} 0. 
    \end{equation*}
    If further, we have
    \begin{equation} \label{eqn:asssemidiscrconvinputdata}
        \|u_0 - \mathcal{K}_{\kappa_{n}} \vec{u}_0^{\kappa_n}\|_{L^\infty(\Omega)^d}\in O(\kappa), \|v_0 - \mathcal{K}_{\kappa_{n}} \vec{v}_0^{\kappa_n}\|_{L^\infty(\Omega)^d} \in O(\kappa),  \|\mathbf{b} - \mathcal{K}_{\kappa_{n}} \vec{\mathbf{b}}_{\kappa_n}\|_{C^0([0,T], L^\infty(\Omega)^d)} \in O(\kappa), 
    \end{equation}
    then 
    \begin{equation}\label{eqn:convrateressemidisr}
        \|\mathbf{u} - \mathcal{K}_{\kappa_{n}}\vec{\mathbf{u}}^{\kappa_n}\|_{C^1([0,T], L^\infty(\Omega)^d)} \in O(\kappa)
    \end{equation}

We define $\mathcal{K}_\kappa^2: (\mathbb{R}^d)^{I^\kappa}\times (\mathbb{R}^d)^{I^\kappa} \rightarrow L^\infty(\Omega)^{2d},\ (\vec{u},\vec{v}) \mapsto (\mathcal{K}_\kappa \vec{u}, \mathcal{K}_\kappa \vec{v})$, similarly \\ $\mathcal{P}_\kappa^2: L^\infty(\Omega)^{2d} \rightarrow (\mathbb{R}^d)^{I^\kappa}\times (\mathbb{R}^d)^{I^\kappa}, (\phi, \psi) \mapsto (\mathcal{P}_\kappa\phi, \mathcal{P}_\kappa\psi)$. Using Lemma \ref{lemm:transport}, we transport the reduced semi-discrete equations (\ref{eqn:semdiscreqred}) to $L^\infty(\Omega)^d\times L^\infty(\Omega)^d$,
\begin{equation*}
    \begin{rcases}
        \tfrac{d}{dt}{\mathbf{u}}_{Red}^{\kappa_n}(t) = \mathcal{K}_{\kappa_{n}}^2 \vec{G}_{\kappa_n}((\mathcal{P}_{\kappa_n}^2{\mathbf{u}}_{Red}^{\kappa_n})_t, t) \\
        {\mathbf{u}}_{Red}^{\kappa_n}(0) =  \mathcal{K}_{\kappa_{n}}^2\vec{u}_{0, Red}^{\kappa_n}.
    \end{rcases}
\end{equation*}
Through direct substitution, one can verify that the unique solution $\mathbf{u}_{Red}^{\kappa_n}$ fulfills $\mathbf{u}_{Red}^{\kappa_n} = \mathcal{K}_\kappa^2 \vec{\mathbf{u}}^{\kappa_n}_{Red}$ in $C^1([0,T], L^\infty(\Omega)^{2d})$, where $\vec{\mathbf{u}}_{Red}^{\kappa_n}$ is the unique solution to (\ref{eqn:semdiscreqred}). This follows from Lemma \ref{lemm:transport}, $\mathcal{P}_{\kappa_n}^2 \circ \mathcal{K}_{\kappa_{n}}^2 = \mathrm{id}\times \mathrm{id}$, and from the fact that $\operatorname{img}\mathcal{K}_{\kappa_{n}}^2$ is a closed linear subspace of $L^\infty(\Omega)^{2d}$. 
We then have
\begin{align*}
    [\mathbf{u}_{Red} - \mathbf{u}^{\kappa_n}_{Red}](t) &= [\mathbf{u}_{Red} - \mathbf{u}^{\kappa_n}_{Red}](0) + \int_{0}^t \tfrac{d}{dt}[\mathbf{u}_{Red} - \mathbf{u}^{\kappa_n}_{Red}](s) \ \mathbf{d} s \\
    &= \begin{pmatrix}
        u_0 -\mathcal{K}_{\kappa_{n}}\vec{u}_0^{\kappa_n} \\
        v_0 -\mathcal{K}_{\kappa_{n}} \vec{v}_0^{\kappa_n}
    \end{pmatrix} 
    +\int_{0}^t \begin{pmatrix}
        \dot{\mathbf{u}}(s) - \mathcal{K}_{\kappa_{n}}\dot{\vec{\mathbf{u}}}^{\kappa_n}(s)\\
        F((\mathbf{u})_s)+ \mathbf{b}(s) - \mathcal{K}_{\kappa_{n}}\vec{F}_{\kappa_n}(({\vec{\mathbf{u}}}^{\kappa_n})_s) -\mathcal{K}_{\kappa_{n}}\vec{\mathbf{b}}_{\kappa_n}(s) 
    \end{pmatrix}\ \mathbf{d} s \\
    &= \begin{pmatrix}
        u_0 - \mathcal{K}_{\kappa_{n}}\vec{u}_0^{\kappa_n} \\
        v_0 - \mathcal{K}_{\kappa_{n}} \vec{v}_0^{\kappa_n}
    \end{pmatrix} 
    + \int_{0}^t \begin{pmatrix}
        0\\
         \mathbf{b}(s)-\mathcal{K}_{\kappa_{n}}\vec{\mathbf{b}}_{\kappa_n}(s) 
    \end{pmatrix} 
    \ \mathbf{d} s\\
    &\quad\quad\quad\quad\quad\quad\quad\quad+\int_{0}^t \begin{pmatrix}
        \dot{\mathbf{u}}(s) - \mathcal{K}_{\kappa_{n}}\dot{\vec{\mathbf{u}}}^{\kappa_n}(s)\\
        F((\mathbf{u})_s) - \mathcal{K}_{\kappa_{n}} \vec{F}_{\kappa_n}(({\vec{\mathbf{u}}}^{\kappa_n})_s)
    \end{pmatrix}\ \mathbf{d} s.
\end{align*}
This leads to, using Proposition \ref{prop:discrrhserr},
\begin{align*}
    E(t) &:= \|[\mathbf{u}^{\kappa_n}_{Red} - \mathbf{u}_{Red}](t)\|_{L^\infty(\Omega)^{2d}} \\
    &\leq \underbrace{\|u_0 - \mathcal{K}_{\kappa_{n}} \vec{u}_0^{\kappa_n}\|_{L^\infty(\Omega)^d} +  \|v_0 - \mathcal{K}_{\kappa_{n}} \vec{v}_0^{\kappa_n}\|_{L^\infty(\Omega)^d} + T\|\mathbf{b} - \mathcal{K}_{\kappa_{n}} \vec{\mathbf{b}}_{\kappa_n}\|_{C^0([0,T], L^\infty(\Omega)^d)}}_{=: \alpha_2^{\kappa_n}} \\
    &\quad+\int_{0}^t \begin{Vmatrix}
        \|\dot{\mathbf{u}}(s) - \mathcal{K}_{\kappa_{n}}\dot{\vec{\mathbf{u}}}^{\kappa_n}(s)\|_{L^\infty(\Omega)^d} \\
        \beta \Big(\max_{0\leq \tau \leq s}\|\mathbf{u}(\tau) -\mathcal{K}_{\kappa_{n}}\vec{\mathbf{u}}(\tau)\|_{L^\infty(\Omega)^d}\Big) + \alpha_{\kappa_n}
    \end{Vmatrix}_\infty \ \mathbf{d} s  \\
    &\leq \alpha_2^{\kappa_n} + t \alpha_{\kappa_n} \\
    &\quad + \int_0^{t} \max(1, \beta) \begin{Vmatrix}
    \max_{0\leq \tau \leq s}\|\dot{\mathbf{u}}(\tau) - \mathcal{K}_{\kappa_{n}}\dot{\vec{\mathbf{u}}}(\tau)\|_{L^\infty(\Omega)^d} \\
    \max_{0\leq \tau \leq s}\|\mathbf{u}(\tau) - \mathcal{K}_{\kappa_{n}}\vec{\mathbf{u}}(\tau)\|_{L^\infty(\Omega)^d}
    \end{Vmatrix}_\infty\ \mathbf{d} s \\
    &\leq  \alpha_2^{\kappa_n} + t \alpha_{\kappa_n}\\
    &\quad + \int_0^{t} \max(1, \beta) 
    \max_{0\leq \tau \leq s}\|{\mathbf{u}}_{Red}(\tau) - \mathcal{K}_{\kappa_{n}}^2{\vec{\mathbf{u}}}_{Red}(\tau)\|_{L^\infty(\Omega)^{2d}}\ \mathbf{d} s.
\end{align*}
Defining 
\begin{align}
    A^{\kappa_n}(t) &:=  \alpha_2^{\kappa_n} + t \alpha_{\kappa_n}\geq 0, \label{eqn:defAkapp}\\
    B&:= \max(1, \beta)\geq 0, \nonumber
\end{align}
we then obtain for all $t\in [0,T]$,
\begin{align*}
    E(t)\leq A^{\kappa_n}(t) + \int_0^{t} B \max_{0\leq \tau \leq s} E(\tau) \ \mathbf{d} s,
\end{align*}
with $A^{\kappa_n}$ non-decreasing, such that we further have for $\Delta(t) := \max_{0\leq s \leq t} E(s)$,
\begin{equation*}
    \Delta(t) \leq A^{\kappa_n}(t) + \int_0^{t} B\Delta(s) \ \mathbf{d} s.
\end{equation*}
Applying the Gr\"onwall inequality now yields, for all $t\in [0,T]$,
\begin{equation}
\label{eqn:groenonDel}
    0 \leq E(t) \leq \Delta(t) \leq A^{\kappa_n}(t) \operatorname{exp}\big(tB\big).
\end{equation}
Due to Assumptions \ref{ass:numconv}, Proposition \ref{prop:discrrhserr} and (\ref{eqn:defAkapp}), we then obtain
\begin{equation*}
    A^{\kappa_n} \Rightarrow 0
\end{equation*}
as $n \rightarrow \infty$, which using (\ref{eqn:groenonDel}) leads to, for all $t\in [0,T]$,
\begin{equation*}
    0 \leq E(t) \leq\Delta(t) \leq \Delta(T) \searrow 0
\end{equation*}
for $n\rightarrow \infty$. If (\ref{eqn:asssemidiscrconvinputdata}) holds, we immediately obtain $\alpha_2^{\kappa} \in O(\kappa)$ and therefore $\|A^\kappa\|_{C^{0}([0,T])} \in O(\kappa)$ using the rates in Proposition \ref{prop:discrrhserr}, implying (\ref{eqn:convrateressemidisr}) via (\ref{eqn:groenonDel}).

We define the following.
\begin{enumerate}
    \item ${\hat{G}}_h: L^\infty_{\text{ptw}}([-T,0], (\mathbb{R}^d)^{I^\kappa} \times (\mathbb{R}^d)^{I^\kappa}) \times [0,T] \rightarrow (\mathbb{R}^d)^{I^\kappa} \times (\mathbb{R}^d)^{I^\kappa} $ with 
    \begin{align*}
        {\hat{G}}_h((\phi,\psi)^\top, t) = \begin{pmatrix}
        \psi(0)\\
        \vec{F}_\kappa(\tau_{-h}\phi) + \vec{\mathbf{b}}_\kappa(t)
    \end{pmatrix}.
    \end{align*}
    where $\tau_{-h}$ shifts the map by $h$ to the right, extending it by the value at $-T$ on the left. That is, for $\mathbf{a} \in L^\infty_{\text{ptw}}([-T, 0], X)$ and some Banach Space $X$, we define similarly to the existing shift operator, 
    \begin{equation*}
        [\tau_{-h}\mathbf{a}](s) := \begin{cases}
            \mathbf{a}(s-h) & s\geq -T+h\\
            \mathbf{a}(-T)  & \text{else.}
        \end{cases}
    \end{equation*}
    \item Let $\vec{\mathbf{u}}_{Red}^\kappa$ be the unique solution to (\ref{eqn:semdiscreqred}). We then define the {consistency residual} $K^{N,n}_\kappa$ for $1\leq n \leq N$ as
    \begin{align}\label{eqn:defstabres}
        K^{N,n}_\kappa := \tfrac{1}{h}( \vec{\mathbf{u}}_{Red}^\kappa(t_{n-1})-\vec{\mathbf{u}}_{Red}^\kappa(t_{n}) )+ {\hat{G}}_h((\vec{\mathbf{u}}^\kappa_{Red})_{t_n}, t_{n-1}).
    \end{align}
    \item We then define
\begin{equation}
\label{eqn:redfulldiscrsol}
    \hat{\mathbf{u}}_\kappa^{n,N} := \begin{pmatrix}
        \vec{\mathbf{u}}_\kappa^{n,N} \\
        \frac{\vec{\mathbf{u}}_\kappa^{n,N}-\vec{\mathbf{u}}_\kappa^{n-1,N}}{h}
    \end{pmatrix} =: \begin{pmatrix}
        \vec{\mathbf{u}}_\kappa^{n,N} \\
        \vec{\mathbf{v}}_\kappa^{n,N}
    \end{pmatrix} \in (\mathbb{R}^d)^{I^\kappa}\times(\mathbb{R}^d)^{I^\kappa}
\end{equation}
to equivalently reformulate (\ref{eqn:discrprob}) to 
\begin{equation}
\label{eqn:redfulldiscr}
    0 =  \hat{\mathbf{u}}_\kappa^{n-1,N} -\hat{\mathbf{u}}_\kappa^{n,N}+  h\begin{pmatrix}
         (\hat{\mathbf{u}}_\kappa^{n,N})_2 \\
         \vec{F}_\kappa(\operatorname{IP}_{n}((\hat{\mathbf{u}}^{...n-1,N}_\kappa)_1))+ \vec{\mathbf{b}}_\kappa(t_{n-1})
    \end{pmatrix}.
\end{equation}
\item We define the discretization error at $t_n$ as
\begin{equation}\label{eqn:defediscr}
    e_n := \vec{\mathbf{u}}_{Red}^\kappa (t_n) - \hat{\mathbf{u}}_\kappa^{n,N}.
\end{equation}
\end{enumerate}

\label{lemm:stabineq}
    We have for all $N \in \mathbb{N}$, $1\leq n \leq N$ and all $\delta/\sqrt{d}>\kappa >0$, that
    \begin{align*}
        (1-h)\|e_n\|_\infty& \leq h\|K^{N,n}_\kappa\|_\infty+ \|e_{n-1}\|_\infty \\
       &\quad + hL_{\vec{F}}\|\operatorname{IP}_{n}((\hat{\mathbf{u}}^{...n-1,N}_\kappa)_1)) - ((\vec{\mathbf{u}}_{Red}^\kappa)_1)_{t_{n-1}}\|_{L^\infty_{\text{ptw}}([-T,0], (\mathbb{R}^d)^{I^\kappa})},
    \end{align*}
    where $\vec{\mathbf{u}}_{Red}^\kappa$ is the unique solution to (\ref{eqn:semdiscreqred}) and $\hat{\mathbf{u}}^{n,N}_\kappa$ as given in (\ref{eqn:redfulldiscrsol}) with the $\mathbf{u}^{n,N}_\kappa$ as given in (\ref{eqn:discrprob}).

Subtracting (\ref{eqn:redfulldiscr}) from (\ref{eqn:defstabres}) yields
    \begin{equation*}
            h K^{N,n}_\kappa = e_{n-1} -e_{n} - h\begin{pmatrix}
        (\hat{\mathbf{u}}_\kappa^{n,N})_2 - (\vec{\mathbf{u}}_{Red}^\kappa)_2(t_n) \\
        \vec{F}_\kappa(\operatorname{IP}_{n}((\hat{\mathbf{u}}^{...n-1,N}_\kappa)_1))) - \vec{F}_\kappa(((\vec{\mathbf{u}}_{Red}^\kappa)_1)_{t_{n-1}})
    \end{pmatrix}.
    \end{equation*}
    Rearranging the terms and applying the norm and then Proposition \ref{prop:LScontdiscrrhs} then yields the claim.

\label{lemm:aprioriboundssemidiscrete}
    Let Assumptions \ref{ass:numconv} hold and $\kappa_n \searrow 0$ with $\kappa_n < \frac{\delta}{\sqrt{d}}$ for all $n\in\mathbb{N}$. Define
    \begin{align*}
        R:= \sup_{n\in \mathbb{N}} (\|\vec{u}_0^{\kappa_n}\|_\infty + \|\vec{v}_0^{\kappa_n}\|_\infty + \|\vec{\mathbf{b}}^{\kappa_n}\|_{C^0([0,T], (\mathbb{R}^d)^{I^\kappa})}) < \infty
    \end{align*}
    Then, for all $n\in \mathbb{N}$, $t, t' \in [0,T]$, we have
    \begin{align*}
        \|\vec{\mathbf{u}}^{\kappa_n}_{\text{Red}}(t)\|_\infty\leq M_0:=R(1+T)\,e^{L_{\vec{G}}T},\quad \|\vec{\mathbf{u}}^{\kappa_n}_{\text{Red}}(t)-\vec{\mathbf{u}}^{\kappa_n}_{\text{Red}}(t')\|_\infty\leq M_1 |t-t'|,\quad M_1:=L_{\vec{G}}M_0 + R .
    \end{align*}

\label{theo:fullconv}
    Let Assumptions \ref{ass:numconv} hold. Further, let $(N_k)_{k\in \mathbb{N}}\subset \mathbb{N}$ be such that $N_k \xrightarrow[]{k\rightarrow \infty} \infty$ and $0<\kappa_k \searrow 0$ as $k\nearrow \infty$. Denote the unique solution to (\ref{eqn:conteq}) in reduced form as $\mathbf{u}_{Red} \in C^1([0,T], L^\infty(\Omega)^d\times L^\infty(\Omega)^d)$, and $(\hat{\mathbf{u}}_{\kappa_k}^{n, N_k})_{0\leq n \leq N_k}$ as given by (\ref{eqn:discrprob}) represented as in (\ref{eqn:redfulldiscrsol}). Then, we have
    \begin{equation*}
        \lim_{k\rightarrow \infty} \max_{0\leq n \leq N_k} \| \mathbf{u}_{Red}(t_n^{N_k}) - \mathcal{K}_{\kappa_{k}}^2\hat{\mathbf{u}}_{\kappa_k}^{n, N_k}\|_{L^\infty(\Omega)^d\times L^\infty(\Omega)^d} = 0.
    \end{equation*}
    Further, if $\mathbf{b}$ is Lipschitz continuous in $t$, as well as 
    \begin{equation}\label{eqn:assreginputdataconv}
    \begin{aligned}
        &\|\mathcal{K}_{\kappa_{k}}\vec{\mathbf{b}}_{\kappa_k} - \mathbf{b}\|_{C^0([0,T], L^\infty(\Omega)^d)} \in O(\kappa_k),\ \|u_0 - \mathcal{K}_{\kappa_{k}}\vec{u}_0\|_{L^\infty(\Omega)^d} \in O(\kappa_k),\\
        &\hspace{3.1cm}\|v_0 - \mathcal{K}_{\kappa_{k}}\vec{v}_0\|_{L^\infty(\Omega)^d} \in O(\kappa_k)
    \end{aligned}
    \end{equation}
    then we obtain
    \begin{equation*}
       \max_{0\leq n \leq N_k} \| \mathbf{u}_{Red}(t_n^{N_k}) - \mathcal{K}_{\kappa_{k}}^2\hat{\mathbf{u}}_{\kappa_k}^{n, N_k}\|_{L^\infty(\Omega)^d\times L^\infty(\Omega)^d} \in O(1/N_k+ \kappa_k).
    \end{equation*}

Define $h:= T/N_k$. We assume without loss of generality that $h<1$. Using the convergence of the input data as assumed in Assumptions \ref{ass:numconv}, we obtain $\kappa',\delta'>0$ for every $\epsilon>0$ such that
\begin{align}
    &\|\vec{\mathbf{b}}_\kappa(t)-\vec{\mathbf{b}}_\kappa(t')\|_\infty \leq \|\mathcal{K}_\kappa\vec{\mathbf{b}}_\kappa(t)-\mathbf{b}(t)\| +\|\mathbf{b}(t)-\mathbf{b}(t')\| +\|\mathcal{K}_\kappa\vec{\mathbf{b}}_\kappa(t')-\mathbf{b}(t')\| \leq \epsilon,\nonumber\\
    &\|\mathbf{u}_{Red}(0) - (\mathcal{K}_\kappa\vec{{u}}_{0}^{\kappa}, \mathcal{K}_\kappa\vec{{v}}_{0}^{\kappa})\|\leq \epsilon, \ \ \  \|\mathcal{K}_\kappa\vec{\mathbf{b}}_\kappa(0)- \mathbf{b}(0)\| \leq \epsilon\label{eqn:inputappr}
\end{align}
for all $0<\kappa < \kappa'$ and $|t'-t| \leq \delta'$. \newline
If (\ref{eqn:assreginputdataconv}) holds, we obtain stronger convergence result,
\begin{equation} \label{eqn:sharperboundsinputdata}
    \begin{aligned}
        &\|\vec{\mathbf{b}}_\kappa(t)-\vec{\mathbf{b}}_\kappa(t')\|_\infty \leq \|\mathcal{K}_\kappa\vec{\mathbf{b}}_\kappa(t)-\mathbf{b}(t)\| +\|\mathbf{b}(t)-\mathbf{b}(t')\| +\|\mathcal{K}_\kappa\vec{\mathbf{b}}_\kappa(t')-\mathbf{b}(t')\|\in O(h+\kappa),\\
        &\|\mathbf{u}_{Red}(0) - (\mathcal{K}_\kappa\vec{{u}}_{0}^{\kappa}, \mathcal{K}_\kappa\vec{{v}}_{0}^{\kappa})\|\in O(\kappa), \ \ \  \|\mathcal{K}_\kappa\vec{\mathbf{b}}_\kappa(0)- \mathbf{b}(0)\| \in O(\kappa)
    \end{aligned}
\end{equation}
The Lipschitz continuity of $\vec{\mathbf{u}}_{\kappa, Red}$ implies that there is a $M^N_\kappa\geq 0$ for all $0<\kappa$ and $0<N$ such that 
\begin{equation}\label{eqn:IPred}
\begin{aligned}
    &\|\operatorname{IP}_{n}((\hat{\mathbf{u}}^{0,...n-1,N}_\kappa)_1) - ((\vec{\mathbf{u}}_{Red}^\kappa)_1)_{t_{n-1}}\|_{L^\infty_{\text{ptw}}([-T,0], (\mathbb{R}^d)^{I^\kappa})} \\
    &\leq \max_{1\leq k \leq n}\|\operatorname{IP}_{n}((\hat{\mathbf{u}}^{0,...n-1,N}_\kappa)_1) - ((\vec{\mathbf{u}}_{Red}^\kappa)_1)_{t_{n-1}}\|_{L^\infty_{\text{ptw}}([-hk,-h(k-1)], (\mathbb{R}^d)^{I^\kappa})} \\
    &\leq \max_{0\leq k\leq n-1} \|e_k\|_\infty + \sup_{t\in [0,T]} \sup_{|t-t'|<h}\|\vec{\mathbf{u}}_{Red}^\kappa(t) - \vec{\mathbf{u}}_{Red}^\kappa(t')\| \\
    &\leq M^N_\kappa + \max_{0\leq k \leq n-1} \|e_{k}\|_\infty.
\end{aligned}
\end{equation}
and, with Lemma \ref{lemm:aprioriboundssemidiscrete},
\begin{equation}\label{eqn:Tconv}
    O(h) \ni M^{N_k}_{\kappa_k} \xrightarrow[]{k\rightarrow \infty} 0.
\end{equation}
We further define
\begin{equation*}
    K^{N}_\kappa := \max_{1\leq k \leq N} \|K^{N,k}_\kappa\|_\infty.
\end{equation*}
We now aim to show that $K^N_\kappa$ converges to zero.
To this end, we have for all $t \in [t_{n-1}, t_n]$, $h<\delta'$
\begin{align*}
    &\left\|\begin{pmatrix}
          \dot{\vec{\mathbf{u}}}_{}^\kappa(t)\\
        \vec{F}_\kappa((\vec{\mathbf{u}}^{\kappa})_{t}) + \vec{\mathbf{b}}_\kappa(t) \end{pmatrix} -  {\hat{G}}_h((\vec{\mathbf{u}}^\kappa_{Red})_{t_n}, t_{n-1})\right\|\\
     &=\left\|\begin{pmatrix}
          \dot{\vec{\mathbf{u}}}_{}^\kappa(t)\\
        \vec{F}_\kappa((\vec{\mathbf{u}}^{\kappa})_{t}) + \vec{\mathbf{b}}_\kappa(t)
    \end{pmatrix} - \begin{pmatrix}
        \dot{\vec{\mathbf{u}}}_{}^\kappa(t_{n})\\
        \vec{F}_\kappa((\vec{\mathbf{u}}^{\kappa})_{t_{n-1}}) + \vec{\mathbf{b}}_\kappa(t_{n-1}) 
    \end{pmatrix} \right\|_{\infty}\\
    &\leq \|\dot{\mathbf{u}}_{}^\kappa(t)-\dot{\mathbf{u}}_{}^\kappa(t_{n})\|_{\infty} + \|\vec{F}((\mathbf{u}_{\kappa})_{t})- \vec{F}((\mathbf{u}_{\kappa})_{t_{n-1}}) \|_{\infty} + \|\vec{\mathbf{b}}_\kappa(t)-\vec{\mathbf{b}}_\kappa(t_{n-1})\|_{\infty}\\
    &\leq M_1h+ {L_{\vec{F}}}M_1h + \epsilon
\end{align*}
which implies that
\begin{align*}
    \|K^{N,n}_\kappa\|_\infty &= \left \|\frac{1}{h} \int_{t_{n-1}}^{t_n}\begin{pmatrix}
          \dot{\vec{\mathbf{u}}}^{\kappa}(t)\\
        \vec{F}((\vec{\mathbf{u}}^{\kappa})_{t}) + \vec{\mathbf{b}}_\kappa(t)
    \end{pmatrix} - \begin{pmatrix}
        \dot{\vec{\mathbf{u}}}^{\kappa}(t_{n})\\
        \vec{F}((\vec{\mathbf{u}}^{\kappa})_{t_{n-1}}) + \vec{\mathbf{b}}_\kappa(t_{n-1}) 
    \end{pmatrix}  \ \mathbf{d} t \right\|_\infty \\
    &\leq M_1h+ {L_{\vec{F}}}M_1h + \epsilon
\end{align*}
This yields
\begin{equation}\label{eqn:KNconv}
    K^{N_k}_{\kappa_k} \xrightarrow[]{k\rightarrow \infty} 0.
\end{equation}
Note that if (\ref{eqn:assreginputdataconv}) holds, we obtain using (\ref{eqn:sharperboundsinputdata}) that $K^{N_k}_{\kappa_k} \in O(h + \kappa)$. 
We denote the discretization error in $t^{N_k}_n$ as defined in (\ref{eqn:defediscr}) for $N_k$ and $\kappa_k$ as $e^k_n :=  \vec{\mathbf{u}}_{Red}^{\kappa_k}(t_n^{N_k}) - \hat{\mathbf{u}}_{\kappa_k}^{n,N_k}$.
We also note that, using (\ref{eqn:inputappr}) and Proposition \ref{prop:LScontdiscrrhs},
\begin{align*}
    \|e_0^k\|_\infty &\leq \|\vec{u}_{0}^\kappa -\vec{\mathbf{u}}^\kappa(0)\|_\infty + \Big\|\tfrac{\vec{\mathbf{u}}_\kappa^{0,N}-\vec{\mathbf{u}}_\kappa^{-1,N}}{h} -\dot{\vec{\mathbf{u}}}^\kappa(0) \Big\|_\infty \\
    &\leq \|\tfrac{1}{2}h(\vec{F}(\operatorname{IP}_1(\vec{u}_{0}^\kappa))+ \vec{\mathbf{b}}_\kappa(0))\|_\infty \leq \tfrac{1}{2}h (L_{\vec{F}}M_0 + R)
\end{align*} 
This yields
\begin{equation}\label{eqn:e0conv}
    O(h) \ni \|e_0^k\|_\infty \xrightarrow[]{k\rightarrow \infty} 0.
\end{equation}
We now define the final error bound sequence $a_n^k$ such that $a_0^k = \|e_0^k\|_\infty$ and for $n\geq 1$, 
\begin{equation}\label{eqn:defan}
    a_n^k := \frac{1}{1-h}\left(hK^{N_k}_{\kappa_k} + a_{n-1} + hL_{\vec{F}}\left(M^{N_k}_{\kappa_k} + \max_{0\leq s \leq n-1} a_{s}\right)\right).
\end{equation}
Using Lemma \ref{lemm:stabineq} and (\ref{eqn:IPred}), we see that
\begin{equation*}
\|e_n\|_{\infty} \leq a_n^k
\end{equation*}
for all $k$ and $0 \leq n\leq N$.

Since all factors on the right hand side of (\ref{eqn:defan}) are non-negative (we assume $0<h<1$) and $a_0^k\geq 0$, we conclude that $a_n^k \geq a_{n-1}^k$ for $n\geq 1$, therefore the above equation is equivalent to
\begin{equation}\label{eqn:finrecdiscr}
    a_n^k = \frac{1}{1-h}\left(hK^{N_k}_{\kappa_k} +hL_{\vec{F}} M^{N_k}_{\kappa_k} + (1+hL_{\vec{F}})a_{n-1}^k\right).
\end{equation}
For $a^* := - \frac{K^{N_k}_{\kappa_k} +L_{\vec{F}}M^{N_k}_{\kappa_k}}{(1+L_{\vec{F}})}$, we have that
\begin{equation*}
    a^* = \frac{1}{1-h}\left(hK^{N_k}_{\kappa_k} +hL_{\vec{F}} M^{N_k}_{\kappa_k} + (1+hL_{\vec{F}})a^*\right),
\end{equation*}
as well as that $a^{hom}_n := C_k \left(\frac{1+hL_{\vec{F}}}{1-h}\right)^n$ for $n\geq 0$, fulfills
\begin{equation*}
    a_n^{hom} = \frac{1}{1-h}\left((1+hL_{\vec{F}})a_{n-1}^{hom}\right)
\end{equation*}
for all $C_k\in \mathbb{R}$ and $n\geq 1$. Therefore $a_n^{hom} + a^*$ parameterizes all solutions to (\ref{eqn:finrecdiscr}) over $C_k\in \mathbb{R}$.   Given $a_0^k = \|e_0^k\|_\infty$, we then must have 
\begin{equation*}
    C_k = a_0^k - a^*.
\end{equation*}
An explicit formula for the bounds $a_n^k$ is therefore given for all $0 \leq n\leq N^k$ by 
\begin{equation*}
    a_n^k = \left( \|e_0^k\|_\infty+  \frac{K^{N_k}_{\kappa_k} +L_{\vec{F}}M^{N_k}_{\kappa_k}}{(1+L_{\vec{F}})}\right) \left(\frac{1+hL_{\vec{F}}}{1-h}\right)^n - \frac{K^{N_k}_{\kappa_k} +L_{\vec{F}}M^{N_k}_{\kappa_k}}{(1+L_{\vec{F}})}.
\end{equation*}
We then finally have
\begin{equation}\label{eqn:expbound}
    \left(\frac{1+hL_{\vec{F}}}{1-h}\right)^n \leq \left(\frac{1+\tfrac{T}{N_k}L_{\vec{F}}}{1-\tfrac{T}{N_k}}\right)^{N_k} = \left(1+\tfrac{T}{N_k}L_{\vec{F}}\right)^{N_k}\left(1-\tfrac{T}{N_k}\right)^{-N_k}\rightarrow \operatorname{exp}(T(1+L_{\vec{F}}))< \infty
\end{equation}

This finally yields, for all $k\in\mathbb{N}$,
\begin{equation}\label{eqn:convindiscr}
    \begin{aligned}
        &\max_{0\leq n \leq N_k}\|\vec{\mathbf{u}}_{Red}^{\kappa_k}(t_n^{N_k}) - \hat{\mathbf{u}}_{\kappa_k}^{n,N_k}\|_\infty \\
        &\leq \left( \|e_0^k\|_\infty+  \frac{K^{N_k}_{\kappa_k} +L_{\vec{F}}M^{N_k}_{\kappa_k}}{(1+L_{\vec{F}})}\right)\left(\frac{1+\tfrac{T}{N^k}L_{\vec{F}}}{1-\tfrac{T}{N_k}}\right)^{N^k} - \frac{K^{N_k}_{\kappa_k} +L_{\vec{F}}M^{N_k}_{\kappa_k}}{(1+L_{\vec{F}})} \\
        &\quad \xrightarrow[k\nearrow \infty]{(\ref{eqn:expbound}), (\ref{eqn:KNconv}), (\ref{eqn:Tconv}), (\ref{eqn:e0conv})} 0
    \end{aligned}
\end{equation}
Again, if (\ref{eqn:assreginputdataconv}) holds, we further obtain
\begin{align*}
     &\left( \|e_0^k\|_\infty+  \frac{K^{N_k}_{\kappa_k} +L_{\vec{F}}M^{N_k}_{\kappa_k}}{(1+L_{\vec{F}})}\right)\left(\frac{1+\tfrac{T}{N^k}L_{\vec{F}}}{1-\tfrac{T}{N_k}}\right)^{N^k} - \frac{K^{N_k}_{\kappa_k} +L_{\vec{F}}M^{N_k}_{\kappa_k}}{(1+L_{\vec{F}})} \in O(\kappa +h).
\end{align*}
Finally, we have for all $0\leq n \leq N^k$ and all $\kappa_k$, that 
\begin{align*}
    &\max_{0\leq n \leq N_k}\|\mathbf{u}_{Red}(t_n^{N_k}) - \mathcal{K}_\kappa^2\hat{\mathbf{u}}^{n,N_k}_{\kappa_k}\|_{L^\infty(\Omega)^d}\\
    &\leq \|\mathbf{u}_{Red} -  \mathcal{K}_\kappa^2\vec{\mathbf{u}}^{\kappa_k}_{Red}\|_{C^0([0,T], L^\infty(\Omega)^d)} +\max_{0\leq n \leq N_k} \|\vec{\mathbf{u}}_{Red}^{\kappa_k}(t_n^{N_k}) - \hat{\mathbf{u}}_{\kappa_k}^{n,N_k}\|_\infty, 
\end{align*}
which yields the claim via Theorem \ref{theo:convsemidiscr} and (\ref{eqn:convindiscr}). If (\ref{eqn:assreginputdataconv}) holds, Theorem \ref{theo:convsemidiscr} gives us a rate for the first term, resulting in
\begin{align*}
        &\|\mathbf{u}_{Red} -  \mathcal{K}_\kappa^2\vec{\mathbf{u}}^{\kappa_k}_{Red}\|_{C^0([0,T], L^\infty(\Omega)^d)} +\max_{0\leq n \leq N_k} \|\vec{\mathbf{u}}_{Red}^{\kappa_k}(t_n^{N_k}) - \hat{\mathbf{u}}_{\kappa_k}^{n,N_k}\|_\infty \in O(\kappa) + O(\kappa + h)
\end{align*}

Let the Assumptions \ref{ass:numconv}, \ref{ass:quadweights} hold. We also require $\Omega$ to satisfy an interior cone condition. Further, let $(N_k)_{k\in \mathbb{N}}\subset \mathbb{N}$ be such that $N_k \xrightarrow[]{k\rightarrow \infty} \infty$ and $0<\kappa_k \searrow 0$ as $k\nearrow \infty$. Denote the unique solution to (\ref{eqn:conteq}) as $\mathbf{u}_{} \in C^2([0,T], L^\infty(\Omega)^d)$, and $(\vec{\mathbf{u}}_{\kappa_k}^{n, N_k})_{0\leq n \leq N_k}$ as given by (\ref{eqn:discrprob}). Then, we obtain
    \begin{equation*}
        \lim_{k\rightarrow \infty} \sup_{0\leq l \leq N_k} \|\gamma_{\mathbf{u}}(\cdot, t_l)  - \mathcal{K}_\kappa'\vec{\gamma}_{\vec{\mathbf{u}}_{\kappa_k}}^{l, N_k}\|_{L^\infty(\Omega)} = 0. 
    \end{equation*}
    with $\mathcal{K}_\kappa': \mathbb{R}^{I^\kappa} \rightarrow L^\infty(\Omega)$ being the scalar equivalent of $\mathcal{K}_\kappa$ given by $\vec{u} \mapsto \sum_{i} \chi_{\Omega_i}\vec{u}_i$. \par
    If $\mathbf{b}$ is Lipschitz continuous in $t$ and the input data fulfills (\ref{eqn:assreginputdataconv}), then
    \begin{align*}
         \sup_{0\leq l \leq N_k} \|\gamma_{\mathbf{u}}(\cdot, t_l)  - \mathcal{K}_\kappa'\vec{\gamma}_{\vec{\mathbf{u}}_{\kappa_k}}^{l, N_k}\|_{L^\infty(\Omega)}  \in O(1/N_k+\kappa_k).
    \end{align*}

We drop the $k$ subscript from $\kappa, N$ for convenience. First, we see that $\operatorname{vol}(\Omega \cap B_{\delta}(x)) \leq \operatorname{vol}(B_\delta(0))$ is bounded from above as well as from below for some $0<c_{ICC}< \operatorname{vol}(\Omega \cap B_{\delta}(x))$ uniformly in $x$, 
    given by the interior cone condition of $\Omega$.\newline
    Since we also have
    \begin{align*}
        |\operatorname{vol}(\Omega \cap B_{\delta}(x)) - \sum_{i\not=j} w_{ij}V_j| \leq \operatorname{vol}(B_{\delta + 3\sqrt{d}\kappa/2}(0)) - \operatorname{vol}(B_{\delta - 3\sqrt{d}\kappa/2}(0)) + \kappa^d \in O(\kappa),
    \end{align*}
    supplying lower bounds for $\sum_{i\not=j} w_{ij}V_j$ in the limit, we obtain
    \begin{equation}\label{eqn:convvoldiff}
        \left|\frac{1}{\operatorname{vol}(\Omega \cap B_{\delta}(x))} - \Big(\sum_{i\not=j} w_{ij}V_j\Big)^{-1}\right| \in O(\kappa)
    \end{equation}
    We then obtain for all $i\in I^\kappa$ and $x\in \Omega_i$ and $0 \leq n \leq N$,
    \begin{equation}
        \begin{aligned}
            &c_{ICC}|\gamma_{\mathbf{u}}(x, t_n)  - (\vec{\gamma}_{\vec{\mathbf{u}}_\kappa}^{n, N})_i|\nonumber\\
            &\leq c_{ICC} \left|\frac{1}{\operatorname{vol}(\Omega \cap B_{\delta}(x))} - \Big(\sum_{i\not=j} w_{ij}V_j\Big)^{-1}\right|\Big(\sum_{i\not=j} w_{ij}V_j\Big) \\
            &+\Big|\int_{\Omega \cap B_{\delta}(x)} \mu(\operatorname*{ess\,sup}_{0\leq s\leq t_n} \mathcal{S}(\mathbf{u}(s), x',x)) \ \mathbf{d} x' - \sum_{i\not=j} w_{ij} V_j \mu(\max_{0\leq l\leq n} \mathcal{S}^{ij}(\vec{\mathbf{u}}^{l,N}_{\kappa}))\Big| \nonumber\\
        \end{aligned}
    \end{equation}
    Since the $\sum_{j\not=i} V_j w_{ij}$ terms converge as $\kappa \searrow 0$ by Assumption \ref{ass:quadweights}, we have with (\ref{eqn:convvoldiff}) that the first summand vanishes in $O(\kappa)$. We now focus on the second, bounding it by 
    \begin{align}
        &\Big|\sum_{i\not=j} \int_{\Omega_j}  \chi_{[0,\delta]}(\|x-x'\|_2)\Big(\mu(\operatorname*{ess\,sup}_{-T\leq s\leq 0} \mathcal{S}(\mathbf{u}_{t_n}(s), x',x)) \nonumber \\
        &\phantom{==============} - \mu(\operatorname*{ess\,sup}_{-T\leq s\leq 0} \mathcal{S}^{ij}(\operatorname{IP}^{n+1}(\vec{\mathbf{u}}^{0,...,n,N}_{\kappa})(s)))\Big) \ \mathbf{d} x' \Big| \label{eqn:firstsummandconvinteg}\\
        &\quad+ \sum_{i\not=j} \int_{\Omega_j} |w_{ij} - \chi_{[0,\delta]}(\|x-x'\|_2)|\mu(\max_{0\leq l\leq n} \mathcal{S}^{ij}(\vec{\mathbf{u}}^{l,N}_{\kappa}))\ \mathbf{d} x'\nonumber + \kappa^d
    \end{align}
    where the $\kappa^d$ factor comes from the $i=j$ cell of the continuous integral. The last summand can be bounded by 
    \begin{align*}
        &\sum_{i\not=j} \int_{\Omega_j} |w_{ij} - \chi_{[0,\delta]}(\|x-x'\|_2)|\ \mathbf{d} x'\leq \operatorname{vol}(B_{\delta + 3\sqrt{d}\kappa/2}(0)) - \operatorname{vol}(B_{\delta - 3\sqrt{d}\kappa/2}(0)) \in O(\kappa)
    \end{align*}

    Turning our attention to the first summand in (\ref{eqn:firstsummandconvinteg}), we obtain using Lemma \ref{lemm:auxbnd} applicable to the $\operatorname{IP}$ term since all of its values are taken on sets of measure greater $0$,
    \begin{align*}
        &\Big|\sum_{i\not=j} \int_{\Omega_j} \chi_{[0,\delta]}(\|x-x'\|_2)\Big(\mu(\operatorname*{ess\,sup}_{-T\leq s\leq 0} \mathcal{S}(\mathbf{u}_{t_n}(s), x',x))  - \mu(\operatorname*{ess\,sup}_{-T\leq s\leq 0} \mathcal{S}^{ij}(\operatorname{IP}^{n+1}(\vec{\mathbf{u}}^{0,...,n,N}_{\kappa})(s))) \ \mathbf{d} x'\Big) \Big| \\
        &\leq  \Big| \sum_{i\not=j} \int_{\Omega_j}  \Big((\sqrt{d}+1)\tfrac{\sqrt{d}\ell\chi_{[0,\delta]}(\|x-x'\|_2)}{\|x'-x\|_2}\Big)( 2\|\operatorname{IP}^{n+1}(\vec{\mathbf{u}}^{0,...,n,N}_{\kappa})-\mathbf{u}_{t_n}\|_{L^\infty_{\text{ptw}}([-T,0],L^\infty(\Omega)^d)}\\
        &\qquad+ (S^+_1+2)\sqrt{d}\kappa) \ \mathbf{d} x' \Big| \\
        &\leq \Big[(S^+_1+2)(\sqrt{d}+1)d\ell\kappa + 2(\sqrt{d}+1)\sqrt{d}\ell \|\operatorname{IP}^{n+1}(\vec{\mathbf{u}}^{0,...,n,N}_{\kappa})-\mathbf{u}_{t_n}\|_{
    L^\infty_{\text{ptw}}([-T,0],L^\infty(\Omega)^d)} \Big] \\
        &\quad \times\int_{B_{\delta}(0)} \|\zeta\|_2^{-1} \ \mathbf{d} \zeta
    \end{align*}
    Due to $d\geq 2$ the last integral over $\|\zeta\|_2^{-1}$ is finite, as well as
     \begin{align*}
          &\|\operatorname{IP}^{n+1}(\vec{\mathbf{u}}^{0,...,n,N}_{\kappa})-\mathbf{u}_{t_n}\|_{L^\infty_{\text{ptw}}([-T,0],L^\infty(\Omega)^d)}\\
          &\leq Lh + \max_{0 \leq l \leq n} \| \mathbf{u}(t_l) - \mathcal{K}_\kappa \vec{\mathbf{u}}^{l,N}_\kappa \|_{L^\infty(\Omega)^d}
     \end{align*}
    for the Lipschitz constant $L= \|\dot{\mathbf{u}}\|_{L^\infty_{\text{ptw}}([0,T], L^\infty(\Omega)^d)} < \infty$ and $h:= T/N$. 
    The result of Theorem \ref{theo:fullconv} now applies.

\label{rm:abouttheassumptionspt2} In order to circumvent the effect of the strong convergence requirements in Assumptions \ref{ass:numconv} as well as to use a more practical norm to measure the convergence, attempts to reformulate the equations on an $L^p(\Omega)^d$ space with $1\leq p<\infty$ are naturally interesting. However, these run into problems due to the $\operatorname*{ess\,sup}$ term in the argument of $\mu$, as the spatial $L^p(\Omega)^d$ norm cannot be swapped with the $L^\infty([0,t])$ norm that the essential supremum represents, even for jointly measurable representatives. This causes the Lipschitz continuity proof as given above for the peridynamic operator $F$ to fail. \par
    A mathematically natural approach to circumvent this would be to equivalently rewrite
    \begin{equation*}
        \mu(\operatorname*{ess\,sup}_{0\leq s\leq t} \mathcal{S}(\mathbf{u}(s), x', x))
    \end{equation*}
    as, using $p=\infty$ and the symbolic convention $1/\infty := 0$ for the exponent,
    \begin{equation*}
        \mu(S^+_0 + \tfrac{1}{t_c^{1/p}}\|\max(0, \mathcal{S}(\mathbf{u}(s),x',x)-S^+_0)\|_{L^p([0,t])}) 
    \end{equation*}
    which naturally also allows for $p<\infty$. The $t_c>0$ parameter is an additional material parameter included to get rid of the $s^{1/p}$ unit of the $\|\cdot\|_{L^p}$ norm due to the integral over $t$ in it and has the same physical unit as the time $t$. For $p=1$ and $t_c=1$ this would yield the damage term as described in \cite{Emmrich2016} and similar to \cite{Lipton2018}, which also uses a time integral. Note that the $1<p<\infty$ then transitions between the damage term in \cite{Emmrich2016} corresponding to $p=1$ and the one in \cite{WP_FRAC, SillMeshFree} corresponding to $p=\infty$. Additionally, the models for $p < \infty$ introduce a time-dependence into how the models accumulate damage, as the maximum is replaced with an integral accumulating stretch over the threshold $S^+_0$ over time. That is, minimally crossing the threshold $S^+_0$ for long enough will result in large damage and, conversely, a large stretch over a sufficiently short time span will not result in significant damage. As noted in \cite{Emmrich2016}, this allows modeling fatigue through cyclic loading, as each cycle adds to the accumulated stretch even if the maximum stretch is left unaffected. The parameter $t_c>0$ can be understood to model the sensitivity to strain, since it is scaling the accumulated damage accordingly. \par
    With this change one could attempt to establish similar convergence results with the assumptions and convergence formulated in the $L^p(\Omega)^d$ norm. Rigorous treatment of these models is however subject to further research.

\label{ass:contexptw}
    \begin{enumerate}
    \item A horizon $\delta>0$ and a non-increasing measurable weighting function $\omega_\delta: (0,\infty) \rightarrow \mathbb{R}_{\geq 0}$, fulfilling
    \begin{equation}
        \mathcal{L} :=\int_{\mathbb{R}^d} \frac{\omega_\delta(\|\zeta\|_2)}{\|\zeta\|_2}\ \mathbf{d} \zeta<\infty.
    \end{equation}
    \item The external body forces are continuous in time,  $\mathbf{b}\in C^0([0, T], L^\infty_{\text{ptw}}(\Omega)^d)$ 
    \item The initial data is pointwise $u_0,v_0 \in L^\infty_{\text{ptw}}(\Omega)^d$
    \item A terminal time $0 <T <\infty$.
    \end{enumerate}

The right hand side of (\ref{eqn:conteq}) as given in (\ref{eqn:defcontF}) can be redefined as $F^{\text{ptw}}: C^0([-T,0], L^\infty_{\text{ptw}}(\Omega)^d) \rightarrow L^\infty_{\text{ptw}}(\Omega)^d$ alongside with $\mathbf{f}$ from (\ref{eqn:defcontfinteg}) to take displacements in $C^0([-T,0], L^\infty_{\text{ptw}}(\Omega)^d)$, without any changes besides removing the representation map $\Gamma$ since the functions at a time point $t$ are no longer equivalence classes.\par
    Let the Assumptions \ref{ass:contexptw} hold. Then, the corresponding equations to (\ref{eqn:conteq}) posed on \newline $ C^0([-T,0], L^\infty_{\text{ptw}}(\Omega)^d)$, given by
    \begin{equation}
        \label{eqn:conteqptw}
        \begin{rcases}
            \rho\ddot{\mathbf{u}}_{\text{ptw}}(t) = F^{\text{ptw}}((\mathbf{u}_{\text{ptw}})_t) + \mathbf{b}(t)\\ 
            \mathbf{u}_{\text{ptw}}(0) = u_0 \\
            \dot{\mathbf{u}}_{\text{ptw}}(0) = v_0
        \end{rcases}
    \end{equation} 
    have a unique solution $\mathbf{u}_{\text{ptw}} \in C^2([0,T], L^\infty_{\text{ptw}}(\Omega)^d)$.

The pointwise map $F^{\text{ptw}}$ can be shown to be Lipschitz continuous for some $L_{F^{\text{ptw}}}>0$, 
    \begin{equation*}
        \|F^{\text{ptw}}(\mathbf{u}) - F^{\text{ptw}}(\mathbf{v})\|_{L^\infty_{\text{ptw}}(\Omega)^d} \leq L_{F^{\text{ptw}}}\|\mathbf{u}-\mathbf{v}\|_{C^0([-T,0], L^\infty_{\text{ptw}}(\Omega)^d)}
    \end{equation*}
     for all $\mathbf{u},\mathbf{v}\in C^0([-T,0],L^\infty_{\text{ptw}}(\Omega)^d)$, due to 
     \begin{equation*}
         \operatorname*{ess\,sup}_{-T\leq t\leq 0} \|\mathbf{u}(t,x)\|_\infty =  \sup_{-T\leq t\leq 0} \|\mathbf{u}(t,x)\|_\infty
     \end{equation*}
     for all $x\in \Omega$, as well as
     \begin{equation*}
         \sup_{-T\leq t\leq 0} \sup_{x\in\Omega}\|\mathbf{u}(t,x)\|_\infty  = \sup_{x\in\Omega} \sup_{-T\leq t\leq 0}\|\mathbf{u}(t,x)\|_\infty. 
     \end{equation*}
     This is analogous to \cite{WP_FRAC}, Lemma 1.
     The rest of the proof is then analogous to \cite{WP_FRAC}, Theorem 2, obtaining a unique solution using a Picard iteration argument.

\label{lemm:unifbndintegcont} Let $x,\hat{x} \in \Omega$, then
    \begin{align}\label{eqn:unifbndcntintegtransl}
        0 \leq \int_{\Omega} \frac{\omega_\delta(\|x'-x\|_2)}{\|x'-\hat{x}\|_2}\ \mathbf{d} x' \leq \mathcal{L}
    \end{align}

Intuitively speaking, the integral in (\ref{eqn:unifbndcntintegtransl})  should behave more nicely than the integral in (\ref{eqn:boundcond}), as $\omega_\delta(z)$  just like $1/z$ is non-increasing for $z>0$, meaning that the largest values multiply in the integrand of (\ref{eqn:boundcond}), but are offset in (\ref{eqn:unifbndcntintegtransl}). To make this thought rigorous, we note that for any measurable set $A\subset\mathbb{R}^d$ and $\operatorname{vol}(A)\leq \operatorname{vol}(B_r(0))$ for some $r>0$ we have
    \begin{equation*}
        \int_{A} \frac{1}{\|\zeta\|_2} \ \mathbf{d} \zeta \leq \int_{B_r(0)} \frac{1}{\|\zeta\|_2}\ \mathbf{d} \zeta.
    \end{equation*}
    That is, the ball around the origin, which is where the singularity is, maximizes the value of the integral over all sets with a given volume $\operatorname{vol}(B_r(0))$. This formalizes the idea of largest values combining if applied to level sets $A=\{x' : \omega_\delta(\|\cdot - x\|_2)>s\}$ for any $s\geq 0$. To use this explicitly, we use the layer cake representation of (\ref{eqn:unifbndcntintegtransl}),  
\begin{align}\label{eqn:ineqhelpunifbndcnttr}
        \int_{\Omega} \frac{\omega_\delta(\|x'-x\|_2)}{\|x'-\hat{x}\|_2}\ \mathbf{d} x' \leq \int_0^\infty\int_{\{x'\in\mathbb{R}^d : \omega_\delta(\|x'-x\|_2) > s\}} \frac{1}{\|x'-\hat{x}\|_2}\ \mathbf{d} x' \ \mathbf{d} s
    \end{align}
   We see that $\operatorname{vol}(\{x'\in\mathbb{R}^d : \omega_\delta(\|x'-x\|_2) > s\}) = \operatorname{vol}(\{x'\in\mathbb{R}^d : \omega_\delta(\|x'-\hat{x}\|_2) > s\})$. Further, the level sets $\{x'\in\mathbb{R}^d : \omega_\delta(\|x'-\hat{x}\|_2) > s\}$ are balls $B_{r_s}(0)$ for some $r_s\geq 0$ dependent on $s\geq 0$, due to the monotonicity and radial symmetry of $\omega_\delta$. With a small translation to allow the assumption $\hat{x}=0$ without loss of generality, we obtain with (\ref{eqn:ineqhelpunifbndcnttr}),
    \begin{equation*}
        \int_0^\infty\int_{\{x'\in\mathbb{R}^d : \omega_\delta(\|x'-x\|_2) > s\}} \frac{1}{\|x'-\hat{x}\|_2}\ \mathbf{d} x' \ \mathbf{d} s\\
        \leq \int_0^\infty\int_{\{x'\in\mathbb{R}^d : \omega_\delta(\|x'-\hat{x}\|_2) > s\}} \frac{1}{\|x'-\hat{x}\|_2}\ \mathbf{d} x' \ \mathbf{d} s\\
        =\mathcal{L}.
    \end{equation*}
    The last equality follows from reversing the layer cake representation again.

\label{prop:contcontsol}
    Let Assumptions \ref{ass:contexptw} hold. There is a representation $\mathbf{u}_{\mathrm{ptw}}\in C^0([0,T], L^\infty_{\mathrm{ptw}}(\Omega;\mathbb{R}^d))$ of the solution $\mathbf{u} \in C^0([0,T], L^\infty(\Omega)^d)$ of (\ref{eqn:conteq}), characterized by $\mathbf{u}_{\mathrm{ptw}}(t) \in L^\infty_{\text{ptw}}(\Omega; \mathbb{R}^d)$ being a representation of $\mathbf{u}(t) \in L^\infty(\Omega)^d$ for all $t\in [0,T]$, such that 
    \begin{enumerate}
        \item If $u_0, v_0 \in L_{\text{ptw}}^\infty(\Omega;\mathbb{R}^d)$ and $\mathbf{b}\in C^0([0,T], L_{\text{ptw}}^\infty(\Omega;\mathbb{R}^d))$ are continuous in a given $x_0\in \Omega$, the latter for all $t\in [0,T]$, then $\mathbf{u}_{\mathrm{ptw}}(t)$ is continuous in $x_0$ for all $t\in [0,T]$. 
        \item Furthermore, if $v_0, u_0\in L_{\text{ptw}}^\infty(\Omega;\mathbb{R}^d)$, $\mathbf{b}(t) \in L_{\text{ptw}}^\infty(\Omega;\mathbb{R}^d)$ are locally Lipschitz continuous in a given $x_0\in\Omega$, uniform with respect to $t\in [0,T]$, then $\mathbf{u}_{\mathrm{ptw}}(t)$ is locally Lipschitz continuous in $x_0$ as well, with a Lipschitz constant independent of $t\in [0,T]$. If the Lipschitz continuity is global in the input data, then $\mathbf{u}_{\text{ptw}}$ is globally Lipschitz continuous.
    \end{enumerate}

We first attend to the weighting function $\omega_\delta$. Again, we will use Lemma \ref{lemm:shellbounds} made applicable by Assumptions \ref{ass:contexptw}, to bound the term
    \begin{align*}
         \int_{\mathbb{R}^d} |\omega_\delta(\|x-x'\|_2) - \omega_\delta(\|\hat{x}-x'\|_2)| \ \mathbf{d} x',
    \end{align*}
    We again have for $s:= \|x-\hat{x}\|_2$, $r(x'):= \|x-x'\|_2$,  $l(x'):= \|\hat{x}-x'\|_2$, that
    \begin{align*}
        &\int_{\mathbb{R}^d} |\omega_\delta(\|x-x'\|_2) - \omega_\delta(\|\hat{x}-x'\|_2)| \ \mathbf{d} x' \\
        &\leq \int_{\|x-x'\|\geq 2s} \omega_\delta(r(x') - s) - \omega_\delta(r(x') +s) \ \mathbf{d} x' + \int_{\|x-x'\|\leq 2s} \omega_\delta(l(x')) + \omega_\delta(r(x')) \ \mathbf{d} x' \\
        &\leq 3\cdot 2^{d-1} s \mathcal{L} + 3s \mathcal{L} + 2s \mathcal{L},
    \end{align*}
    due to $r(x') \leq 2s$ implying $l(x') \leq 3s$. We then obtain using $s = \|x-\hat{x}\|_2$
\begin{align}\label{eqn:BndKernelLS}
        \int_{\mathbb{R}^d} |\omega_\delta(\|x-x'\|_2) - \omega_\delta(\|\hat{x}-x'\|_2)| \ \mathbf{d} x' \leq C_d\mathcal{L}\|x-\hat{x}\|_2
    \end{align}
    with $C_d:= 3\cdot 2^{d-1} + 5$.\newline

    Now, for 1: The continuity follows from (\ref{eqn:fingroenregcontsol}), (\ref{eqn:BndKernelLS}) and the requirements in 1. We additionally apply the dominated convergence theorem to obtain
    \begin{equation*}
        \int_0^t \|\mathbf{b}(s,x)-\mathbf{b}(s,\hat{x})\|_\infty \ \mathbf{d} s \rightarrow 0
    \end{equation*}
    as $\hat{x} \rightarrow x$.\newline
    For 2: The local Lipschitz continuity follows from (\ref{eqn:BndKernelLS}) and from the requirements in 2 applied to (\ref{eqn:fingroenregcontsol}). The existence of a Lipschitz constant $L^*$ such that $L_t \leq L^* <\infty$ for all $0\leq t \leq T$ follows from choosing $t=T$.

\label{rm:bonddiscuss}
The constants in (\ref{eqn:fingroenregcontsol}) result from a worst-case Gr\"onwall argument and carry no quantitative information. For the parameters of Section \ref{sec:numerics} ($E = 100$, $\delta = 0.2$, $T = 0.1$), the argument of the hyperbolic cosine in (\ref{eqn:fingroenregcontsol}) is approximately $3\cdot 10^3$; it remains of order $10^2$ even if $\ell$, $g^+$ and $(S_1^- + 1)^{-1}$ are all set to one, compensating for the fact that these constants are potentially active only on small volumes in the horizon. 
Proposition \ref{prop:contcontsol} is therefore to be understood as a purely qualitative statement. Given a fixed $\delta > 0$, continuity and local Lipschitz continuity of the data are preserved, regardless of damage. In particular, the divergence of the bound as $\delta \searrow 0$ does not imply that solutions become steeper. Such divergence is, however, unavoidable if solutions for fixed data are to localize and develop jumps in the limit $\delta \searrow 0$. Whether and how the actual slopes grow as $\delta \searrow 0$ is beyond the present analysis, as is the resolution required to capture them at a given $\delta$. The latter is further studied numerically in Section \ref{sec:numerics}.

For $\mathbf{u},\mathbf{v} \in C^0([-T, 0], L^\infty(\Omega)^d)$
    \begin{equation*}
        \|\mathbf{b}^D(\mathbf{u}) - \mathbf{b}^D(\mathbf{v})\|_{L^\infty(\Omega)^d} \leq L_D \|\mathbf{u}-\mathbf{v}\|_{C^0([-T,0], L^\infty(\Omega)^d)}.
    \end{equation*}
Similarly, for $\vec{\mathbf{u}},\vec{\mathbf{v}} \in C^0([-T, 0], (\mathbb{R}^d)^{I^\kappa})$,
\begin{equation*}
    \|\vec{\mathbf{b}}^D_\kappa(\vec{\mathbf{u}}) - \vec{\mathbf{b}}^D_\kappa(\vec{\mathbf{v}})\|_{\infty} \leq L_{{D}} \|\vec{\mathbf{u}}-\vec{\mathbf{v}}\|_{C^0([-T,0], (\mathbb{R}^d)^{I^\kappa})},
\end{equation*}
for some $L_D>0$ independent of $0 < \kappa \leq \delta/(2\sqrt{d})$.

\newline
Let $\mathbf{u}\in C^0([0,T], L^\infty(\Omega)^d)$ and $\vec{\mathbf{u}} \in C^0([0,T], (\mathbb{R}^d)^{I^\kappa})$, then, for all $t\in [0,T]$,
\begin{equation*}
    \|\mathbf{b}^D(\mathbf{u}_t) - \mathcal{K}_\kappa \vec{\mathbf{b}}^D_\kappa((\vec{\mathbf{u}})_t) \|_{L^\infty(\Omega)^d} \leq \beta^D \Big(\max_{0\leq s \leq t}\|\mathbf{u}(s) - \mathcal{K}_\kappa\vec{\mathbf{u}}(s)\|_{L^\infty(\Omega)^d}\Big) + \alpha^D_\kappa
\end{equation*}
for some $\alpha_\kappa^D, \beta^D \geq 0$, and \begin{equation*}
    O(\kappa) \ni \alpha_\kappa^D \xrightarrow[]{\kappa \searrow 0} 0,\ \ \ \beta^D < \infty
\end{equation*}
for $\kappa \searrow 0$ and $\beta^D$ independent of $0<\kappa\leq \delta/(2\sqrt{d})$.

Let Assumptions \ref{ass:numconv} hold and $\Omega_I$ be an open and bounded set disjoint with $\Omega$. Let $\kappa_n \searrow 0$ and $\vec{\mathbf{u}}^{\kappa_n}\in C^2([0,T], (\mathbb{R}^d)^{I^{\kappa_n}})$ be the solutions to the semi-discrete problem (\ref{eqn:semidiscrprobldirich}), as well as $\mathbf{u}\in C^2([0,T], L^\infty(\Omega)^d)$ the solution to the continuous problem (\ref{eqn:conteqdirich}), then
    \begin{equation*}
        \|\mathbf{u} - \mathcal{K}_{\kappa_{n}}\vec{\mathbf{u}}^{\kappa_n}\|_{C^1([0,T], L^\infty(\Omega)^d)} \xrightarrow[]{n \rightarrow \infty} 0. 
    \end{equation*}
    If further the rates in (\ref{eqn:asssemidiscrconvinputdata}) hold, we have
    \begin{equation}
        \|\mathbf{u} - \mathcal{K}_{\kappa_{n}}\vec{\mathbf{u}}^{\kappa_n}\|_{C^1([0,T], L^\infty(\Omega)^d)} \in O(\kappa)
    \end{equation}
    \hfill \ensuremath{\Box}

\label{lemm:stabineqdirich}
    We have for all $N\in\mathbb{N}$, $1\leq n \leq N$ and all $\delta/\sqrt{d}> \kappa >0$, that
    \begin{align*}
        (1-h)\|e_n\|_\infty& \leq h\|\hat{K}^{N,n}_\kappa\|_\infty+ \|e_{n-1}\|_\infty \\
       &\quad + h(L_{\vec{F}}+L_{{D}})\|\operatorname{IP}_{n}((\hat{\mathbf{u}}^{0,...n-1,N}_\kappa)_1)) - ((\vec{\mathbf{u}}_{Red}^\kappa)_1)_{t_{n-1}}\|_{L^\infty_{\text{ptw}}([-T,0], (\mathbb{R}^d)^{I^\kappa})},
    \end{align*}
    where $\vec{\mathbf{u}}_{Red}^\kappa$ is the unique solution to (\ref{eqn:semidiscrprobldirich}) in reduced form, and $\hat{\mathbf{u}}^{n,N}_\kappa$ again derived from the solutions $\vec{\mathbf{u}}^{n,N}_\kappa$ from (\ref{eqn:discrprobdirich}), just like we did in (\ref{eqn:redfulldiscrsol}).\hfill \ensuremath{\Box}

\label{corol:fullconvdirich}
    Let Assumptions \ref{ass:numconv} hold. Let $\Omega_I$ be open, bounded and disjoint with $\Omega$. Further, let $(N_k)_{k\in \mathbb{N}}\subset \mathbb{N}$ be such that $N_k \xrightarrow[]{k\rightarrow \infty} \infty$ and $0<\kappa_k \searrow 0$. Denote the unique solution to (\ref{eqn:conteqdirich}) in reduced form as $\mathbf{u}_{Red} \in C^1([0,T], L^\infty(\Omega)^d\times  L^\infty(\Omega)^d)$, and the solution constructed using (\ref{eqn:discrprobdirich}) expressed like in (\ref{eqn:redfulldiscrsol}) as $(\hat{\mathbf{u}}_{\kappa_k}^{n, N_k})_{0\leq n \leq N_k}$. Then, we have
    \begin{equation*}
        \lim_{k\rightarrow \infty} \max_{0\leq n \leq N_k} \| \mathbf{u}_{Red}(t_n^{N_k}) - \mathcal{K}_{\kappa_{k}}^2\hat{\mathbf{u}}_{\kappa_k}^{n, N_k}\|_{L^\infty(\Omega)^d\times L^\infty(\Omega)^d} = 0.
    \end{equation*}
    Further, if $\mathbf{b}$ is Lipschitz continuous in $t$, as well as 
    \begin{align}
        &\|\mathcal{K}_{\kappa_{k}}\vec{\mathbf{b}}_{\kappa_k} - \mathbf{b}\|_{C^0([0,T], L^\infty(\Omega)^d)} \in O(\kappa_k),\ \|u_0 - \mathcal{K}_{\kappa_{k}}\vec{u}_0\|_{L^\infty(\Omega)^d} \in O(\kappa_k),\\
        &\hspace{3.1cm}\|v_0 - \mathcal{K}_{\kappa_{k}}\vec{v}_0\|_{L^\infty(\Omega)^d} \in O(\kappa_k)
    \end{align}
    then we obtain
    \begin{equation*}
       \max_{0\leq n \leq N_k} \| \mathbf{u}_{Red}(t_n^{N_k}) - \mathcal{K}_{\kappa_{k}}^2\hat{\mathbf{u}}_{\kappa_k}^{n, N_k}\|_{L^\infty(\Omega)^d\times L^\infty(\Omega)^d} \in O(1/N_k+ \kappa_k).
    \end{equation*} \hfill \ensuremath{\Box}

\label{lemm:alt34weights}
For all $i\in I^\kappa$ and $x\in \Omega_i$,
\begin{align*}
        &0\leq \sum_{j\not=i} \int_{\Omega_j}\frac{\omega_\delta^{ij}}{\|x'-x\|_2} \ \mathbf{d} x' \leq \mathcal{L}^{\text{discr}},\\
        &0\leq \sum_{j\not=i} V_j \frac{\omega_\delta^{ij}}{\|x_j-x_i\|_2}\leq \mathcal{L}^{\text{discr}},
\end{align*}
for a constant $\mathcal{L}^{\text{discr}}>0$ independent of $\delta/\sqrt{d}> \kappa>0$.

\label{lemm:alt39weights}
Let $i\in I^\kappa$, then, for all $x\in \Omega_i$,
\begin{equation*}
   \sum_{i\not=j}\int_{\Omega_j} |\omega_\delta^{ij}-\omega_\delta(\|x'-x\|_2)| \ \mathbf{d} x' \leq D_\kappa,
\end{equation*}
with $0<D_\kappa< \infty$ independent of $x$ and $i$ as well as $ O(\kappa) \ni D_\kappa \searrow 0$ as $\kappa \searrow 0$, with $0< \kappa < \delta/\sqrt{d}$.
